StringPiece16::const_iterator findNonAlphaNumericAndNotInSet(const StringPiece16& str,
 const StringPiece16& allowedChars) {
 const auto endIter = str.end();
 for (auto iter = str.begin(); iter != endIter; ++iter) {
 char16_t c = *iter;
 if ((c >= u'a' && c <= u'z') ||
 (c >= u'A' && c <= u'Z') ||
 (c >= u'0' && c <= u'9')) {
 continue;
 }

 bool match = false;
 for (char16_t i : allowedChars) {
 if (c == i) {
                match = true;
 break;
 }
 }

 if (!match) {
 return iter;
 }
 }
 return endIter;
}

int regulator_list_voltage(struct regulator *regulator, unsigned selector)
{
	struct regulator_dev *rdev = regulator->rdev;
	const struct regulator_ops *ops = rdev->desc->ops;
	int ret;

	if (rdev->desc->fixed_uV && rdev->desc->n_voltages == 1 && !selector)
		return rdev->desc->fixed_uV;

	if (ops->list_voltage) {
		if (selector >= rdev->desc->n_voltages)
			return -EINVAL;
		mutex_lock(&rdev->mutex);
		ret = ops->list_voltage(rdev, selector);
		mutex_unlock(&rdev->mutex);
	} else if (rdev->supply) {
		ret = regulator_list_voltage(rdev->supply, selector);
	} else {
		return -EINVAL;
	}

	if (ret > 0) {
		if (ret < rdev->constraints->min_uV)
			ret = 0;
		else if (ret > rdev->constraints->max_uV)
			ret = 0;
	}

	return ret;
}

