init_user_id_from_FQN (const char * _fqn) {

  char * uid = NULL;
  char * domain = NULL;
  char * fqn = NULL;
  char default_uid [] = "nobody";

  if (_fqn) {
    fqn = strdup (_fqn);
    uid = fqn;

    char * pAt = strchr (fqn, '@');
    if (pAt) {
      *pAt='\0';
      domain = pAt+1;
    }
  }

  if (uid == NULL) {
    uid = default_uid;
  }

  int rc = init_user_ids (uid, domain);
  dprintf (D_FULLDEBUG, "Switching to user %s@%s, result = %d\n", uid, domain, rc);

  if (fqn)
    free (fqn);

  return rc;
}

polkit_backend_interactive_authority_check_authorization_finish (PolkitBackendAuthority  *authority,
                                                                 GAsyncResult            *res,
                                                                 GError                 **error)
{
  GSimpleAsyncResult *simple;
  PolkitAuthorizationResult *result;

  simple = G_SIMPLE_ASYNC_RESULT (res);

  g_warn_if_fail (g_simple_async_result_get_source_tag (simple) == polkit_backend_interactive_authority_check_authorization);

  result = NULL;

  if (g_simple_async_result_propagate_error (simple, error))
    goto out;

  result = g_object_ref (g_simple_async_result_get_op_res_gpointer (simple));

 out:
  return result;
}

