static void cliOutputHelp(int argc, char **argv) {
    int i, j, len;
    int group = -1;
    helpEntry *entry;
    struct commandHelp *help;

    if (argc == 0) {
        cliOutputGenericHelp();
        return;
    } else if (argc > 0 && argv[0][0] == '@') {
        len = sizeof(commandGroups)/sizeof(char*);
        for (i = 0; i < len; i++) {
            if (strcasecmp(argv[0]+1,commandGroups[i]) == 0) {
                group = i;
                break;
            }
        }
    }

    assert(argc > 0);
    for (i = 0; i < helpEntriesLen; i++) {
        entry = &helpEntries[i];
        if (entry->type != CLI_HELP_COMMAND) continue;

        help = entry->org;
        if (group == -1) {
            /* Compare all arguments */
            if (argc == entry->argc) {
                for (j = 0; j < argc; j++) {
                    if (strcasecmp(argv[j],entry->argv[j]) != 0) break;
                }
                if (j == argc) {
                    cliOutputCommandHelp(help,1);
                }
            }
        } else {
            if (group == help->group) {
                cliOutputCommandHelp(help,0);
            }
        }
    }
    printf("\r\n");
}

static void CleanupBadExtensionKeys(const FilePath& root_dir,
                                    PrefService* prefs) {
  const DictionaryValue* dictionary =
      prefs->GetDictionary(ExtensionPrefs::kExtensionsPref);
  std::map<std::string, std::string> remapped_keys;
  for (DictionaryValue::key_iterator i = dictionary->begin_keys();
       i != dictionary->end_keys(); ++i) {
    DictionaryValue* ext;
    if (!dictionary->GetDictionaryWithoutPathExpansion(*i, &ext))
      continue;

    int location;
    FilePath::StringType path_str;
    if (!ext->GetInteger(kPrefLocation, &location) ||
        !ext->GetString(kPrefPath, &path_str)) {
      continue;
    }

    if (location != Extension::LOAD)
      continue;

    const std::string& prefs_id(*i);
    FilePath path(path_str);
    if (!path.IsAbsolute()) {
      path = root_dir.Append(path);
    }
    std::string computed_id = Extension::GenerateIdForPath(path);

    if (prefs_id != computed_id) {
      remapped_keys[prefs_id] = computed_id;
    }
  }

  if (!remapped_keys.empty()) {
    DictionaryPrefUpdate update(prefs, ExtensionPrefs::kExtensionsPref);
    DictionaryValue* update_dictionary = update.Get();
    for (std::map<std::string, std::string>::const_iterator i =
            remapped_keys.begin();
        i != remapped_keys.end();
        ++i) {
      if (update_dictionary->HasKey(i->second)) {
        CHECK(update_dictionary->RemoveWithoutPathExpansion(i->first, NULL));
        continue;
      }
      Value* extension_prefs = NULL;
      CHECK(update_dictionary->RemoveWithoutPathExpansion(
          i->first, &extension_prefs));
      update_dictionary->SetWithoutPathExpansion(i->second, extension_prefs);
    }

    prefs->ScheduleSavePersistentPrefs();
  }
}

quantifiers_memory_node_info(Node* node)
{
  int r = BODY_IS_EMPTY;

  switch (NODE_TYPE(node)) {
  case NODE_LIST:
  case NODE_ALT:
    {
      int v;
      do {
        v = quantifiers_memory_node_info(NODE_CAR(node));
        if (v > r) r = v;
      } while (IS_NOT_NULL(node = NODE_CDR(node)));
    }
    break;

#ifdef USE_CALL
  case NODE_CALL:
    if (NODE_IS_RECURSION(node)) {
      return BODY_IS_EMPTY_REC; /* tiny version */
    }
    else
      r = quantifiers_memory_node_info(NODE_BODY(node));
    break;
#endif

  case NODE_QUANT:
    {
      QuantNode* qn = QUANT_(node);
      if (qn->upper != 0) {
        r = quantifiers_memory_node_info(NODE_BODY(node));
      }
    }
    break;

  case NODE_BAG:
    {
      BagNode* en = BAG_(node);
      switch (en->type) {
      case BAG_MEMORY:
        if (NODE_IS_RECURSION(node)) {
          return BODY_IS_EMPTY_REC;
        }
        return BODY_IS_EMPTY_MEM;
        break;

      case BAG_OPTION:
      case BAG_STOP_BACKTRACK:
        r = quantifiers_memory_node_info(NODE_BODY(node));
        break;
      case BAG_IF_ELSE:
        {
          int v;
          r = quantifiers_memory_node_info(NODE_BODY(node));
          if (IS_NOT_NULL(en->te.Then)) {
            v = quantifiers_memory_node_info(en->te.Then);
            if (v > r) r = v;
          }
          if (IS_NOT_NULL(en->te.Else)) {
            v = quantifiers_memory_node_info(en->te.Else);
            if (v > r) r = v;
          }
        }
        break;
      }
    }
    break;

  case NODE_BACKREF:
  case NODE_STRING:
  case NODE_CTYPE:
  case NODE_CCLASS:
  case NODE_ANCHOR:
  case NODE_GIMMICK:
  default:
    break;
  }

  return r;
}

