char* _multi_string_alloc_and_copy( LPCWSTR in )
{
char *chr;
int len = 0;

if ( !in )
{
        return in;
}

while ( in[ len ] != 0 || in[ len + 1 ] != 0 )
{
len ++;
}

chr = malloc( len + 2 );

len = 0;
while ( in[ len ] != 0 || in[ len + 1 ] != 0 )
{
chr[ len ] = 0xFF & in[ len ];
len ++;
}
chr[ len ++ ] = '\0';
chr[ len ++ ] = '\0';

return chr;
}

static int do_io_accounting(struct task_struct *task, char *buffer, int whole)
{
 	struct task_io_accounting acct = task->ioac;
 	unsigned long flags;

 	if (whole && lock_task_sighand(task, &flags)) {
 		struct task_struct *t = task;

		task_io_accounting_add(&acct, &task->signal->ioac);
		while_each_thread(task, t)
			task_io_accounting_add(&acct, &t->ioac);

		unlock_task_sighand(task, &flags);
	}
	return sprintf(buffer,
			"rchar: %llu\n"
			"wchar: %llu\n"
			"syscr: %llu\n"
			"syscw: %llu\n"
			"read_bytes: %llu\n"
			"write_bytes: %llu\n"
			"cancelled_write_bytes: %llu\n",
			(unsigned long long)acct.rchar,
			(unsigned long long)acct.wchar,
			(unsigned long long)acct.syscr,
			(unsigned long long)acct.syscw,
			(unsigned long long)acct.read_bytes,
			(unsigned long long)acct.write_bytes,
			(unsigned long long)acct.cancelled_write_bytes);
}

void AudioOutputDevice::OnStreamCreated(
base::SharedMemoryHandle handle,
base::SyncSocket::Handle socket_handle,
int length) {
DCHECK(message_loop()->BelongsToCurrentThread());
#if defined(OS_WIN)
DCHECK(handle);
DCHECK(socket_handle);
#else
DCHECK_GE(handle.fd, 0);
DCHECK_GE(socket_handle, 0);
#endif

// We should only get this callback if stream_id_ is valid.  If it is not,
// the IPC layer should have closed the shared memory and socket handles
// for us and not invoked the callback.  The basic assertion is that when
// stream_id_ is 0 the AudioOutputDevice instance is not registered as a
// delegate and hence it should not receive callbacks.
DCHECK(stream_id_);

  // No-op in the case where the client calls Stop() before OnStreamCreated() is
  // called, otherwise we spin up the thread with a potentially freed
  // |callback_| pointer.
base::AutoLock auto_lock(audio_thread_lock_);
  if (!audio_thread_.get())
    return;

  DCHECK(audio_thread_->IsStopped());
audio_callback_.reset(new AudioOutputDevice::AudioThreadCallback(
audio_parameters_, input_channels_, handle, length, callback_));
  audio_thread_->Start(
      audio_callback_.get(), socket_handle, "AudioOutputDevice");

// We handle the case where Play() and/or Pause() may have been called
// multiple times before OnStreamCreated() gets called.
is_started_ = true;
if (play_on_start_)
PlayOnIOThread();
}

static char *get_pid_environ_val(pid_t pid,char *val){
  char temp[500];
int i=0;
int foundit=0;
FILE *fp;

sprintf(temp,"/proc/%d/environ",pid);

fp=fopen(temp,"r");
if(fp==NULL)
return NULL;


for(;;){
temp[i]=fgetc(fp);

if(foundit==1 && (temp[i]==0 || temp[i]=='\0' || temp[i]==EOF)){
char *ret;
temp[i]=0;
ret=malloc(strlen(temp)+10);
sprintf(ret,"%s",temp);
fclose(fp);
return ret;
}

switch(temp[i]){
case EOF:
fclose(fp);
return NULL;
case '=':
temp[i]=0;
if(!strcmp(temp,val)){
foundit=1;
}
i=0;
break;
case '\0':
i=0;
break;
default:
i++;
}
}
}

