}

return OMX_ErrorNone;
}

default:
return SoftVideoEncoderOMXComponent::internalSetParameter(index, params);
}
}

t42_parse_sfnts( T42_Face    face,
T42_Loader  loader )
{
T42_Parser  parser = &loader->parser;
FT_Memory   memory = parser->root.memory;
FT_Byte*    cur;
FT_Byte*    limit  = parser->root.limit;
FT_Error    error;
FT_Int      num_tables = 0;
    FT_ULong    count, ttf_size = 0;

FT_Long     n, string_size, old_string_size, real_size;
FT_Byte*    string_buf = NULL;
FT_Bool     allocated  = 0;

T42_Load_Status  status;


/* The format is                                */
/*                                              */
/*   /sfnts [ <hexstring> <hexstring> ... ] def */
/*                                              */
/* or                                           */
/*                                              */
/*   /sfnts [                                   */
/*      <num_bin_bytes> RD <binary data>        */
/*      <num_bin_bytes> RD <binary data>        */
/*      ...                                     */
/*   ] def                                      */
/*                                              */
/* with exactly one space after the `RD' token. */

T1_Skip_Spaces( parser );

if ( parser->root.cursor >= limit || *parser->root.cursor++ != '[' )
{
FT_ERROR(( "t42_parse_sfnts: can't find begin of sfnts vector\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

T1_Skip_Spaces( parser );
status          = BEFORE_START;
string_size     = 0;
old_string_size = 0;
count           = 0;

while ( parser->root.cursor < limit )
{
cur = parser->root.cursor;

if ( *cur == ']' )
{
parser->root.cursor++;
goto Exit;
}

else if ( *cur == '<' )
{
T1_Skip_PS_Token( parser );
if ( parser->root.error )
goto Exit;

/* don't include delimiters */
string_size = (FT_Long)( ( parser->root.cursor - cur - 2 + 1 ) / 2 );
if ( FT_REALLOC( string_buf, old_string_size, string_size ) )
goto Fail;

allocated = 1;

parser->root.cursor = cur;
(void)T1_ToBytes( parser, string_buf, string_size, &real_size, 1 );
old_string_size = string_size;
string_size = real_size;
}

else if ( ft_isdigit( *cur ) )
{
if ( allocated )
{
FT_ERROR(( "t42_parse_sfnts: "
"can't handle mixed binary and hex strings\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

string_size = T1_ToInt( parser );
if ( string_size < 0 )
{
FT_ERROR(( "t42_parse_sfnts: invalid string size\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

T1_Skip_PS_Token( parser );             /* `RD' */
if ( parser->root.error )
return;

string_buf = parser->root.cursor + 1;   /* one space after `RD' */

if ( limit - parser->root.cursor < string_size )
{
          FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}
else
parser->root.cursor += string_size + 1;
}

if ( !string_buf )
{
FT_ERROR(( "t42_parse_sfnts: invalid data in sfnts array\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

/* A string can have a trailing zero (odd) byte for padding. */
/* Ignore it.                                                */
if ( ( string_size & 1 ) && string_buf[string_size - 1] == 0 )
string_size--;

if ( !string_size )
{
FT_ERROR(( "t42_parse_sfnts: invalid string\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}

for ( n = 0; n < string_size; n++ )
{
switch ( status )
{
case BEFORE_START:
/* load offset table, 12 bytes */
if ( count < 12 )
{
face->ttf_data[count++] = string_buf[n];
continue;
}
else
{
            num_tables = 16 * face->ttf_data[4] + face->ttf_data[5];
            status     = BEFORE_TABLE_DIR;
            ttf_size   = 12 + 16 * num_tables;

            if ( FT_REALLOC( face->ttf_data, 12, ttf_size ) )
goto Fail;
}
/* fall through */

case BEFORE_TABLE_DIR:
/* the offset table is read; read the table directory */
          if ( count < ttf_size )
{
face->ttf_data[count++] = string_buf[n];
continue;
}
else
{
int       i;
FT_ULong  len;


for ( i = 0; i < num_tables; i++ )
{
FT_Byte*  p = face->ttf_data + 12 + 16 * i + 12;


len = FT_PEEK_ULONG( p );

/* Pad to a 4-byte boundary length */
              ttf_size += ( len + 3 ) & ~3;
}

            status         = OTHER_TABLES;
            face->ttf_size = ttf_size;

/* there are no more than 256 tables, so no size check here */
if ( FT_REALLOC( face->ttf_data, 12 + 16 * num_tables,
                             ttf_size + 1 ) )
goto Fail;
}
/* fall through */

case OTHER_TABLES:
/* all other tables are just copied */
          if ( count >= ttf_size )
{
            FT_ERROR(( "t42_parse_sfnts: too many binary data\n" ));
error = FT_THROW( Invalid_File_Format );
goto Fail;
}
}
face->ttf_data[count++] = string_buf[n];
}
}

T1_Skip_Spaces( parser );
}

MountError PerformFakeMount(const std::string& source_path,
                            const base::FilePath& mounted_path) {
if (mounted_path.empty())
return MOUNT_ERROR_INVALID_ARGUMENT;

// Just create an empty directory and shows it as the mounted directory.
if (!base::CreateDirectory(mounted_path)) {
DLOG(ERROR) << "Failed to create directory at " << mounted_path.value();
return MOUNT_ERROR_DIRECTORY_CREATION_FAILED;
}

// Put a dummy file.
const base::FilePath dummy_file_path =
mounted_path.Append("SUCCESSFULLY_PERFORMED_FAKE_MOUNT.txt");
const std::string dummy_file_content = "This is a dummy file.";
const int write_result = base::WriteFile(
dummy_file_path, dummy_file_content.data(), dummy_file_content.size());
if (write_result != static_cast<int>(dummy_file_content.size())) {
DLOG(ERROR) << "Failed to put a dummy file at "
<< dummy_file_path.value();
return MOUNT_ERROR_MOUNT_PROGRAM_FAILED;
}

return MOUNT_ERROR_NONE;
}

void inet_sock_destruct(struct sock *sk)
{
struct inet_sock *inet = inet_sk(sk);

__skb_queue_purge(&sk->sk_receive_queue);
__skb_queue_purge(&sk->sk_error_queue);

sk_mem_reclaim(sk);

if (sk->sk_type == SOCK_STREAM && sk->sk_state != TCP_CLOSE) {
pr_err("Attempt to release TCP socket in state %d %p\n",
sk->sk_state, sk);
return;
}
if (!sock_flag(sk, SOCK_DEAD)) {
pr_err("Attempt to release alive inet socket %p\n", sk);
return;
}

WARN_ON(atomic_read(&sk->sk_rmem_alloc));
WARN_ON(atomic_read(&sk->sk_wmem_alloc));
WARN_ON(sk->sk_wmem_queued);
WARN_ON(sk->sk_forward_alloc);

	kfree(inet->opt);
dst_release(rcu_dereference_check(sk->sk_dst_cache, 1));
sk_refcnt_debug_dec(sk);
}

