long Cluster::Load(long long& pos, long& len) const {
assert(m_pSegment);
assert(m_pos >= m_element_start);

if (m_timecode >= 0) // at least partially loaded
return 0;

assert(m_pos == m_element_start);
assert(m_element_size < 0);

IMkvReader* const pReader = m_pSegment->m_pReader;

long long total, avail;

const int status = pReader->Length(&total, &avail);

if (status < 0) // error
return status;

assert((total < 0) || (avail <= total));
assert((total < 0) || (m_pos <= total)); // TODO: verify this

pos = m_pos;

long long cluster_size = -1;

{
if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

long long result = GetUIntLength(pReader, pos, len);

if (result < 0) // error or underflow
return static_cast<long>(result);

if (result > 0) // underflow (weird)
return E_BUFFER_NOT_FULL;

// if ((pos + len) > segment_stop)
//    return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long id_ = ReadUInt(pReader, pos, len);

if (id_ < 0) // error
return static_cast<long>(id_);

if (id_ != 0x0F43B675) // Cluster ID
return E_FILE_FORMAT_INVALID;

pos += len; // consume id

// read cluster size

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // weird
return E_BUFFER_NOT_FULL;

// if ((pos + len) > segment_stop)
//    return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long size = ReadUInt(pReader, pos, len);

if (size < 0) // error
return static_cast<long>(cluster_size);

if (size == 0)
return E_FILE_FORMAT_INVALID; // TODO: verify this

pos += len; // consume length of size of element

const long long unknown_size = (1LL << (7 * len)) - 1;

if (size != unknown_size)

cluster_size = size;
}

 pos points to start of payload
#if 0
    len = static_cast<long>(size_);
    if (cluster_stop > avail)
        return E_BUFFER_NOT_FULL;
#endif
long long timecode = -1;
long long new_pos = -1;
bool bBlock = false;

long long cluster_stop = (cluster_size < 0) ? -1 : pos + cluster_size;

for (;;) {
if ((cluster_stop >= 0) && (pos >= cluster_stop))
break;

// Parse ID

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

long long result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // weird
return E_BUFFER_NOT_FULL;

if ((cluster_stop >= 0) && ((pos + len) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long id = ReadUInt(pReader, pos, len);

if (id < 0) // error
return static_cast<long>(id);

if (id == 0)
return E_FILE_FORMAT_INVALID;

// This is the distinguished set of ID's we use to determine
// that we have exhausted the sub-element's inside the cluster
// whose ID we parsed earlier.

if (id == 0x0F43B675) // Cluster ID
break;

if (id == 0x0C53BB6B) // Cues ID
break;

pos += len; // consume ID field

// Parse Size

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // weird
return E_BUFFER_NOT_FULL;

if ((cluster_stop >= 0) && ((pos + len) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long size = ReadUInt(pReader, pos, len);

if (size < 0) // error
return static_cast<long>(size);

const long long unknown_size = (1LL << (7 * len)) - 1;

if (size == unknown_size)
return E_FILE_FORMAT_INVALID;

pos += len; // consume size field

if ((cluster_stop >= 0) && (pos > cluster_stop))
return E_FILE_FORMAT_INVALID;

// pos now points to start of payload

if (size == 0) // weird
continue;

if ((cluster_stop >= 0) && ((pos + size) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if (id == 0x67) { // TimeCode ID
len = static_cast<long>(size);

if ((pos + size) > avail)
return E_BUFFER_NOT_FULL;

timecode = UnserializeUInt(pReader, pos, size);

if (timecode < 0) // error (or underflow)
return static_cast<long>(timecode);

new_pos = pos + size;

if (bBlock)
break;
} else if (id == 0x20) { // BlockGroup ID
bBlock = true;
break;
} else if (id == 0x23) { // SimpleBlock ID
bBlock = true;
break;

}

pos += size;  // consume payload
    assert((cluster_stop < 0) || (pos <= cluster_stop));
}

  assert((cluster_stop < 0) || (pos <= cluster_stop));

if (timecode < 0)  // no timecode found
return E_FILE_FORMAT_INVALID;

if (!bBlock)
return E_FILE_FORMAT_INVALID;

m_pos = new_pos; // designates position just beyond timecode payload
m_timecode = timecode; // m_timecode >= 0 means we're partially loaded

if (cluster_size >= 0)
m_element_size = cluster_stop - m_element_start;

return 0;
}

long long mkvparser::UnserializeUInt(
    IMkvReader* pReader,
    long long pos,
    long long size)
{
    assert(pReader);
    assert(pos >= 0);

    if ((size <= 0) || (size > 8))
        return E_FILE_FORMAT_INVALID;

    long long result = 0;

    for (long long i = 0; i < size; ++i)
    {
        unsigned char b;

        const long status = pReader->Read(pos, 1, &b);

        if (status < 0)
            return status;

        result <<= 8;
        result |= b;

        ++pos;
}

    return result;
}

xfs_attr_shortform_to_leaf(
struct xfs_da_args	*args,
struct xfs_buf		**leaf_bp)
{
xfs_inode_t *dp;
xfs_attr_shortform_t *sf;
xfs_attr_sf_entry_t *sfe;
xfs_da_args_t nargs;
char *tmpbuffer;
int error, i, size;
xfs_dablk_t blkno;
struct xfs_buf *bp;
xfs_ifork_t *ifp;

trace_xfs_attr_sf_to_leaf(args);

dp = args->dp;
ifp = dp->i_afp;
sf = (xfs_attr_shortform_t *)ifp->if_u1.if_data;
size = be16_to_cpu(sf->hdr.totsize);
tmpbuffer = kmem_alloc(size, KM_SLEEP);
ASSERT(tmpbuffer != NULL);
memcpy(tmpbuffer, ifp->if_u1.if_data, size);
sf = (xfs_attr_shortform_t *)tmpbuffer;

xfs_idata_realloc(dp, -size, XFS_ATTR_FORK);
xfs_bmap_local_to_extents_empty(dp, XFS_ATTR_FORK);

bp = NULL;
error = xfs_da_grow_inode(args, &blkno);
if (error) {
/*
* If we hit an IO error middle of the transaction inside
* grow_inode(), we may have inconsistent data. Bail out.
*/
if (error == -EIO)
goto out;
xfs_idata_realloc(dp, size, XFS_ATTR_FORK);	/* try to put */
memcpy(ifp->if_u1.if_data, tmpbuffer, size);	/* it back */
goto out;
}

ASSERT(blkno == 0);
error = xfs_attr3_leaf_create(args, blkno, &bp);
if (error) {
		error = xfs_da_shrink_inode(args, 0, bp);
		bp = NULL;
		if (error)
goto out;
xfs_idata_realloc(dp, size, XFS_ATTR_FORK);	/* try to put */
memcpy(ifp->if_u1.if_data, tmpbuffer, size);	/* it back */
goto out;
}

memset((char *)&nargs, 0, sizeof(nargs));
nargs.dp = dp;
nargs.geo = args->geo;
nargs.firstblock = args->firstblock;
nargs.dfops = args->dfops;
nargs.total = args->total;
nargs.whichfork = XFS_ATTR_FORK;
nargs.trans = args->trans;
nargs.op_flags = XFS_DA_OP_OKNOENT;

sfe = &sf->list[0];
for (i = 0; i < sf->hdr.count; i++) {
nargs.name = sfe->nameval;
nargs.namelen = sfe->namelen;
nargs.value = &sfe->nameval[nargs.namelen];
nargs.valuelen = sfe->valuelen;
nargs.hashval = xfs_da_hashname(sfe->nameval,
sfe->namelen);
nargs.flags = XFS_ATTR_NSP_ONDISK_TO_ARGS(sfe->flags);
error = xfs_attr3_leaf_lookup_int(bp, &nargs); /* set a->index */
ASSERT(error == -ENOATTR);
error = xfs_attr3_leaf_add(bp, &nargs);
ASSERT(error != -ENOSPC);
if (error)
goto out;
sfe = XFS_ATTR_SF_NEXTENTRY(sfe);
}
error = 0;
*leaf_bp = bp;
out:
kmem_free(tmpbuffer);
return error;
}

mwifiex_set_uap_rates(struct mwifiex_uap_bss_param *bss_cfg,
struct cfg80211_ap_settings *params)
{
struct ieee_types_header *rate_ie;
int var_offset = offsetof(struct ieee80211_mgmt, u.beacon.variable);
const u8 *var_pos = params->beacon.head + var_offset;
int len = params->beacon.head_len - var_offset;
u8 rate_len = 0;

rate_ie = (void *)cfg80211_find_ie(WLAN_EID_SUPP_RATES, var_pos, len);
if (rate_ie) {
memcpy(bss_cfg->rates, rate_ie + 1, rate_ie->len);
rate_len = rate_ie->len;
}

rate_ie = (void *)cfg80211_find_ie(WLAN_EID_EXT_SUPP_RATES,
params->beacon.tail,
params->beacon.tail_len);
	if (rate_ie)
memcpy(bss_cfg->rates + rate_len, rate_ie + 1, rate_ie->len);

return;
}

