kg_unseal(minor_status, context_handle, input_token_buffer,
message_buffer, conf_state, qop_state, toktype)
OM_uint32 *minor_status;
gss_ctx_id_t context_handle;
gss_buffer_t input_token_buffer;
gss_buffer_t message_buffer;
int *conf_state;
gss_qop_t *qop_state;
int toktype;
{
krb5_gss_ctx_id_rec *ctx;
unsigned char *ptr;
unsigned int bodysize;
int err;
int toktype2;
int vfyflags = 0;
OM_uint32 ret;

ctx = (krb5_gss_ctx_id_rec *) context_handle;

    if (! ctx->established) {
*minor_status = KG_CTX_INCOMPLETE;
return(GSS_S_NO_CONTEXT);
}

/* parse the token, leave the data in message_buffer, setting conf_state */

/* verify the header */

ptr = (unsigned char *) input_token_buffer->value;


err = g_verify_token_header(ctx->mech_used,
&bodysize, &ptr, -1,
input_token_buffer->length,
vfyflags);
if (err) {
*minor_status = err;
return GSS_S_DEFECTIVE_TOKEN;
}

if (bodysize < 2) {
*minor_status = (OM_uint32)G_BAD_TOK_HEADER;
return GSS_S_DEFECTIVE_TOKEN;
}

toktype2 = load_16_be(ptr);

ptr += 2;
bodysize -= 2;

switch (toktype2) {
case KG2_TOK_MIC_MSG:
case KG2_TOK_WRAP_MSG:
case KG2_TOK_DEL_CTX:
ret = gss_krb5int_unseal_token_v3(&ctx->k5_context, minor_status, ctx,
ptr, bodysize, message_buffer,
conf_state, qop_state, toktype);
break;
case KG_TOK_MIC_MSG:
case KG_TOK_WRAP_MSG:
case KG_TOK_DEL_CTX:
ret = kg_unseal_v1(ctx->k5_context, minor_status, ctx, ptr, bodysize,
message_buffer, conf_state, qop_state,
toktype);
break;
default:
*minor_status = (OM_uint32)G_BAD_TOK_HEADER;
ret = GSS_S_DEFECTIVE_TOKEN;
break;
}

if (ret != 0)
save_error_info (*minor_status, ctx->k5_context);

return ret;
}

static void v9fs_walk(void *opaque)
{
    int name_idx;
   V9fsFidState *newfidp = NULL;
   V9fsPDU *pdu = opaque;
   V9fsState *s = pdu->s;

   err = pdu_unmarshal(pdu, offset, "ddw", &fid, &newfid, &nwnames);
   if (err < 0) {
       pdu_complete(pdu, err);
       return ;
   }
    V9fsFidState *newfidp = NULL;
    V9fsPDU *pdu = opaque;
    V9fsState *s = pdu->s;

    err = pdu_unmarshal(pdu, offset, "ddw", &fid, &newfid, &nwnames);
    if (err < 0) {
       for (i = 0; i < nwnames; i++) {
           err = pdu_unmarshal(pdu, offset, "s", &wnames[i]);
           if (err < 0) {
               goto out_nofid;
           }
           if (name_is_illegal(wnames[i].data)) {
               err = -ENOENT;
               goto out_nofid;
           }
           offset += err;
       }
   } else if (nwnames > P9_MAXWELEM) {
       err = -EINVAL;
       goto out_nofid;
   }
   fidp = get_fid(pdu, fid);
   if (fidp == NULL) {
       err = -ENOENT;
       goto out_nofid;
   }
   v9fs_path_init(&dpath);
   v9fs_path_init(&path);
   /*
    * Both dpath and path initially poin to fidp.
    * Needed to handle request with nwnames == 0
    */
   v9fs_path_copy(&dpath, &fidp->path);
        err = -ENOENT;
        goto out_nofid;
    }

xmlParseNCNameComplex(xmlParserCtxtPtr ctxt) {
    int len = 0, l;
    int c;
    int count = 0;

#ifdef DEBUG
    nbParseNCNameComplex++;
#endif

    /*
     * Handler for more complex cases
     */
    GROW;
    c = CUR_CHAR(l);
    if ((c == ' ') || (c == '>') || (c == '/') || /* accelerators */
	(!xmlIsNameStartChar(ctxt, c) || (c == ':'))) {
	return(NULL);
    }

    while ((c != ' ') && (c != '>') && (c != '/') && /* test bigname.xml */
	   (xmlIsNameChar(ctxt, c) && (c != ':'))) {
 	if (count++ > 100) {
 	    count = 0;
 	    GROW;
 	}
 	len += l;
 	NEXTL(l);
	c = CUR_CHAR(l);
    }
    return(xmlDictLookup(ctxt->dict, ctxt->input->cur - len, len));
}

