}

int dns_read_name(unsigned char *buffer, unsigned char *bufend,
unsigned char *name, char *destination, int dest_len,
                 int *offset)
{
int nb_bytes = 0, n = 0;
int label_len;
unsigned char *reader = name;
char *dest = destination;

while (1) {
/* Name compression is in use */
if ((*reader & 0xc0) == 0xc0) {
/* Must point BEFORE current position */
if ((buffer + reader[1]) > reader)
goto err;

n = dns_read_name(buffer, bufend, buffer + reader[1],
                                         dest, dest_len - nb_bytes, offset);
if (n == 0)
goto err;

}

label_len = *reader;
if (label_len == 0)
goto out;

/* Check if:
*  - we won't read outside the buffer
*  - there is enough place in the destination
*/
if ((reader + label_len >= bufend) || (nb_bytes + label_len >= dest_len))
goto err;

/* +1 to take label len + label string */
label_len++;

memcpy(dest, reader, label_len);

dest     += label_len;
nb_bytes += label_len;
reader   += label_len;
}

out:
/* offset computation:
* parse from <name> until finding either NULL or a pointer "c0xx"
*/
reader  = name;
*offset = 0;
while (reader < bufend) {
if ((reader[0] & 0xc0) == 0xc0) {
*offset += 2;
break;
}
else if (*reader == 0) {
*offset += 1;
break;
}
*offset += 1;
++reader;
}
return nb_bytes;

err:
return 0;
}

krb5_ldap_get_password_policy_from_dn(krb5_context context, char *pol_name,
char *pol_dn, osa_policy_ent_t *policy)
{
krb5_error_code             st=0, tempst=0;
LDAP                        *ld=NULL;
LDAPMessage                 *result=NULL,*ent=NULL;
kdb5_dal_handle             *dal_handle=NULL;
krb5_ldap_context           *ldap_context=NULL;
krb5_ldap_server_handle     *ldap_server_handle=NULL;

/* Clear the global error string */
krb5_clear_error_message(context);

/* validate the input parameters */
if (pol_dn == NULL)
return EINVAL;

*policy = NULL;
SETUP_CONTEXT();
GET_HANDLE();

*(policy) = (osa_policy_ent_t) malloc(sizeof(osa_policy_ent_rec));
if (*policy == NULL) {
st = ENOMEM;
goto cleanup;
}
memset(*policy, 0, sizeof(osa_policy_ent_rec));

LDAP_SEARCH(pol_dn, LDAP_SCOPE_BASE, "(objectclass=krbPwdPolicy)", password_policy_attributes);

ent=ldap_first_entry(ld, result);
    if (ent != NULL) {
        if ((st = populate_policy(context, ld, ent, pol_name, *policy)) != 0)
            goto cleanup;
}

cleanup:
ldap_msgfree(result);
if (st != 0) {
if (*policy != NULL) {
krb5_ldap_free_password_policy(context, *policy);
*policy = NULL;
}
}

krb5_ldap_put_handle_to_pool(ldap_context, ldap_server_handle);
return st;
}

