std::string MediaStreamManager::MakeMediaAccessRequest(
int render_process_id,
int render_frame_id,
int page_request_id,
const StreamControls& controls,
const url::Origin& security_origin,
MediaAccessRequestCallback callback) {
DCHECK_CURRENTLY_ON(BrowserThread::IO);

DeviceRequest* request = new DeviceRequest(
      render_process_id, render_frame_id, page_request_id,
false /* user gesture */, MEDIA_DEVICE_ACCESS, controls,
MediaDeviceSaltAndOrigin{std::string() /* salt */,
std::string() /* group_id_salt */,
security_origin});

const std::string& label = AddRequest(request);

request->media_access_request_cb = std::move(callback);
// Post a task and handle the request asynchronously. The reason is that the
// requester won't have a label for the request until this function returns
// and thus can not handle a response. Using base::Unretained is safe since
// MediaStreamManager is deleted on the UI thread, after the IO thread has
// been stopped.
base::PostTaskWithTraits(FROM_HERE, {BrowserThread::IO},
base::BindOnce(&MediaStreamManager::SetUpRequest,
base::Unretained(this), label));
return label;
}

void NetworkHandler::DeleteCookies(
const std::string& name,
Maybe<std::string> url,
Maybe<std::string> domain,
Maybe<std::string> path,
std::unique_ptr<DeleteCookiesCallback> callback) {
  if (!process_) {
callback->sendFailure(Response::InternalError());
return;
}

if (!url.isJust() && !domain.isJust()) {
callback->sendFailure(Response::InvalidParams(
"At least one of the url and domain needs to be specified"));
}
BrowserThread::PostTask(
BrowserThread::IO, FROM_HERE,
base::BindOnce(
&DeleteCookiesOnIO,
          base::Unretained(
              process_->GetStoragePartition()->GetURLRequestContext()),
          name, url.fromMaybe(""), domain.fromMaybe(""), path.fromMaybe(""),
base::BindOnce(&DeleteCookiesCallback::sendSuccess,
std::move(callback))));
}

_PUBLIC_ bool ldap_encode(struct ldap_message *msg,
DATA_BLOB *result, TALLOC_CTX *mem_ctx)
{
struct asn1_data *data = asn1_init(mem_ctx);
int i, j;


if (!data) return false;

       asn1_push_tag(data, ASN1_SEQUENCE(0));
       asn1_write_Integer(data, msg->messageid);

switch (msg->type) {
case LDAP_TAG_BindRequest: {
struct ldap_BindRequest *r = &msg->r.BindRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_Integer(data, r->version);
               asn1_write_OctetString(data, r->dn,
                                      (r->dn != NULL) ? strlen(r->dn) : 0);

switch (r->mechanism) {
case LDAP_AUTH_MECH_SIMPLE:
/* context, primitive */
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
                       asn1_write(data, r->creds.password,
                                  strlen(r->creds.password));
                       asn1_pop_tag(data);
break;
case LDAP_AUTH_MECH_SASL:
/* context, constructed */
                       asn1_push_tag(data, ASN1_CONTEXT(3));
                       asn1_write_OctetString(data, r->creds.SASL.mechanism,
                                              strlen(r->creds.SASL.mechanism));
if (r->creds.SASL.secblob) {
                               asn1_write_OctetString(data, r->creds.SASL.secblob->data,
                                                      r->creds.SASL.secblob->length);
}
                       asn1_pop_tag(data);
break;
default:
                       return false;
}

               asn1_pop_tag(data);
break;
}
case LDAP_TAG_BindResponse: {
struct ldap_BindResponse *r = &msg->r.BindResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, &r->response);
if (r->SASL.secblob) {
                       asn1_write_ContextSimple(data, 7, r->SASL.secblob);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_UnbindRequest: {
/*             struct ldap_UnbindRequest *r = &msg->r.UnbindRequest; */
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchRequest: {
struct ldap_SearchRequest *r = &msg->r.SearchRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->basedn, strlen(r->basedn));
               asn1_write_enumerated(data, r->scope);
               asn1_write_enumerated(data, r->deref);
               asn1_write_Integer(data, r->sizelimit);
               asn1_write_Integer(data, r->timelimit);
               asn1_write_BOOLEAN(data, r->attributesonly);

if (!ldap_push_filter(data, r->tree)) {
                       return false;
}

               asn1_push_tag(data, ASN1_SEQUENCE(0));
for (i=0; i<r->num_attributes; i++) {
                       asn1_write_OctetString(data, r->attributes[i],
                                              strlen(r->attributes[i]));
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultEntry: {
struct ldap_SearchResEntry *r = &msg->r.SearchResultEntry;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));
for (i=0; i<r->num_attributes; i++) {
struct ldb_message_element *attr = &r->attributes[i];
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attr->name,
                                              strlen(attr->name));
                       asn1_push_tag(data, ASN1_SEQUENCE(1));
for (j=0; j<attr->num_values; j++) {
                               asn1_write_OctetString(data,
attr->values[j].data,
                                                      attr->values[j].length);
}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultDone: {
struct ldap_Result *r = &msg->r.SearchResultDone;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyRequest: {
struct ldap_ModifyRequest *r = &msg->r.ModifyRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));

for (i=0; i<r->num_mods; i++) {
struct ldb_message_element *attrib = &r->mods[i].attrib;
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_enumerated(data, r->mods[i].type);
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attrib->name,
                                              strlen(attrib->name));
                       asn1_push_tag(data, ASN1_SET);
for (j=0; j<attrib->num_values; j++) {
                               asn1_write_OctetString(data,
attrib->values[j].data,
                                                      attrib->values[j].length);

}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}

               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyResponse: {
struct ldap_Result *r = &msg->r.ModifyResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AddRequest: {
struct ldap_AddRequest *r = &msg->r.AddRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));

for (i=0; i<r->num_attributes; i++) {
struct ldb_message_element *attrib = &r->attributes[i];
                       asn1_push_tag(data, ASN1_SEQUENCE(0));
                       asn1_write_OctetString(data, attrib->name,
                                              strlen(attrib->name));
                       asn1_push_tag(data, ASN1_SET);
for (j=0; j<r->attributes[i].num_values; j++) {
                               asn1_write_OctetString(data,
attrib->values[j].data,
                                                      attrib->values[j].length);
}
                       asn1_pop_tag(data);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AddResponse: {
struct ldap_Result *r = &msg->r.AddResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_DelRequest: {
struct ldap_DelRequest *r = &msg->r.DelRequest;
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_write(data, r->dn, strlen(r->dn));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_DelResponse: {
struct ldap_Result *r = &msg->r.DelResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyDNRequest: {
struct ldap_ModifyDNRequest *r = &msg->r.ModifyDNRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_write_OctetString(data, r->newrdn, strlen(r->newrdn));
               asn1_write_BOOLEAN(data, r->deleteolddn);
if (r->newsuperior) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
                       asn1_write(data, r->newsuperior,
                                  strlen(r->newsuperior));
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ModifyDNResponse: {
struct ldap_Result *r = &msg->r.ModifyDNResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_CompareRequest: {
struct ldap_CompareRequest *r = &msg->r.CompareRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->dn, strlen(r->dn));
               asn1_push_tag(data, ASN1_SEQUENCE(0));
               asn1_write_OctetString(data, r->attribute,
                                      strlen(r->attribute));
               asn1_write_OctetString(data, r->value.data,
                                      r->value.length);
               asn1_pop_tag(data);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_CompareResponse: {
struct ldap_Result *r = &msg->r.ModifyDNResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, r);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_AbandonRequest: {
struct ldap_AbandonRequest *r = &msg->r.AbandonRequest;
               asn1_push_tag(data, ASN1_APPLICATION_SIMPLE(msg->type));
               asn1_write_implicit_Integer(data, r->messageid);
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_SearchResultReference: {
struct ldap_SearchResRef *r = &msg->r.SearchResultReference;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_write_OctetString(data, r->referral, strlen(r->referral));
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ExtendedRequest: {
struct ldap_ExtendedRequest *r = &msg->r.ExtendedRequest;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(0));
               asn1_write(data, r->oid, strlen(r->oid));
               asn1_pop_tag(data);
if (r->value) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(1));
                       asn1_write(data, r->value->data, r->value->length);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
case LDAP_TAG_ExtendedResponse: {
struct ldap_ExtendedResponse *r = &msg->r.ExtendedResponse;
               asn1_push_tag(data, ASN1_APPLICATION(msg->type));
               ldap_encode_response(data, &r->response);
if (r->oid) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(10));
                       asn1_write(data, r->oid, strlen(r->oid));
                       asn1_pop_tag(data);
}
if (r->value) {
                       asn1_push_tag(data, ASN1_CONTEXT_SIMPLE(11));
                       asn1_write(data, r->value->data, r->value->length);
                       asn1_pop_tag(data);
}
               asn1_pop_tag(data);
break;
}
default:
               return false;
}

if (msg->controls != NULL) {
               asn1_push_tag(data, ASN1_CONTEXT(0));

for (i = 0; msg->controls[i] != NULL; i++) {
if (!ldap_encode_control(mem_ctx, data,
msg->controls[i])) {
msg->controls[i])) {
DEBUG(0,("Unable to encode control %s\n",
msg->controls[i]->oid));
                               return false;
}
}

               asn1_pop_tag(data);
}

       asn1_pop_tag(data);
       if (data->has_error) {
               asn1_free(data);
               return false;
       }

*result = data_blob_talloc(mem_ctx, data->data, data->length);
asn1_free(data);
return true;
}

static const char *blob2string_talloc(TALLOC_CTX *mem_ctx,
char *result = talloc_array(mem_ctx, char, blob.length+1);
memcpy(result, blob.data, blob.length);
result[blob.length] = '\0';
return result;
}

int tls1_setup_key_block(SSL *s)
{
unsigned char *p;
const EVP_CIPHER *c;
const EVP_MD *hash;
int num;
SSL_COMP *comp;
int mac_type = NID_undef, mac_secret_size = 0;
int ret = 0;

if (s->s3->tmp.key_block_length != 0)
return (1);

    if (!ssl_cipher_get_evp
        (s->session, &c, &hash, &mac_type, &mac_secret_size, &comp,
         SSL_USE_ETM(s))) {
SSLerr(SSL_F_TLS1_SETUP_KEY_BLOCK, SSL_R_CIPHER_OR_HASH_UNAVAILABLE);
return (0);
}

s->s3->tmp.new_sym_enc = c;
s->s3->tmp.new_hash = hash;
s->s3->tmp.new_mac_pkey_type = mac_type;
s->s3->tmp.new_mac_secret_size = mac_secret_size;
num = EVP_CIPHER_key_length(c) + mac_secret_size + EVP_CIPHER_iv_length(c);
num *= 2;

ssl3_cleanup_key_block(s);

if ((p = OPENSSL_malloc(num)) == NULL) {
SSLerr(SSL_F_TLS1_SETUP_KEY_BLOCK, ERR_R_MALLOC_FAILURE);
goto err;
}

s->s3->tmp.key_block_length = num;
s->s3->tmp.key_block = p;

#ifdef SSL_DEBUG
printf("client random\n");
{
int z;
for (z = 0; z < SSL3_RANDOM_SIZE; z++)
printf("%02X%c", s->s3->client_random[z],
((z + 1) % 16) ? ' ' : '\n');
}
printf("server random\n");
{
int z;
for (z = 0; z < SSL3_RANDOM_SIZE; z++)
printf("%02X%c", s->s3->server_random[z],
((z + 1) % 16) ? ' ' : '\n');
}
printf("master key\n");
{
int z;
for (z = 0; z < s->session->master_key_length; z++)
printf("%02X%c", s->session->master_key[z],
((z + 1) % 16) ? ' ' : '\n');
}
#endif
if (!tls1_generate_key_block(s, p, num))
goto err;
#ifdef SSL_DEBUG
printf("\nkey block\n");
{
int z;
for (z = 0; z < num; z++)
printf("%02X%c", p[z], ((z + 1) % 16) ? ' ' : '\n');
}
#endif

if (!(s->options & SSL_OP_DONT_INSERT_EMPTY_FRAGMENTS)
&& s->method->version <= TLS1_VERSION) {
/*
* enable vulnerability countermeasure for CBC ciphers with known-IV
* problem (http://www.openssl.org/~bodo/tls-cbc.txt)
*/
s->s3->need_empty_fragments = 1;

if (s->session->cipher != NULL) {
if (s->session->cipher->algorithm_enc == SSL_eNULL)
s->s3->need_empty_fragments = 0;

#ifndef OPENSSL_NO_RC4
if (s->session->cipher->algorithm_enc == SSL_RC4)
s->s3->need_empty_fragments = 0;
#endif
}
}

ret = 1;
err:
return (ret);
}

std::unique_ptr<StoragePartitionImpl> StoragePartitionImpl::Create(
BrowserContext* context,
bool in_memory,
const base::FilePath& relative_partition_path,
const std::string& partition_domain) {
// Ensure that these methods are called on the UI thread, except for
// unittests where a UI thread might not have been created.
DCHECK(BrowserThread::CurrentlyOn(BrowserThread::UI) ||
!BrowserThread::IsThreadInitialized(BrowserThread::UI));

base::FilePath partition_path =
context->GetPath().Append(relative_partition_path);

std::unique_ptr<StoragePartitionImpl> partition =
base::WrapUnique(new StoragePartitionImpl(
context, partition_path, context->GetSpecialStoragePolicy()));

partition->is_in_memory_ = in_memory;
partition->relative_partition_path_ = relative_partition_path;

// All of the clients have to be created and registered with the
// QuotaManager prior to the QuotaManger being used. We do them
// all together here prior to handing out a reference to anything
// that utilizes the QuotaManager.
partition->quota_manager_ = new storage::QuotaManager(
in_memory, partition_path,
base::CreateSingleThreadTaskRunnerWithTraits({BrowserThread::IO}).get(),
context->GetSpecialStoragePolicy(),
base::BindRepeating(&StoragePartitionImpl::GetQuotaSettings,
partition->weak_factory_.GetWeakPtr()));
scoped_refptr<storage::QuotaManagerProxy> quota_manager_proxy =
partition->quota_manager_->proxy();

// Each consumer is responsible for registering its QuotaClient during
// its construction.
partition->filesystem_context_ = CreateFileSystemContext(
context, partition_path, in_memory, quota_manager_proxy.get());

partition->database_tracker_ = base::MakeRefCounted<storage::DatabaseTracker>(
partition_path, in_memory, context->GetSpecialStoragePolicy(),
quota_manager_proxy.get());

  partition->dom_storage_context_ = new DOMStorageContextWrapper(
BrowserContext::GetConnectorFor(context),
in_memory ? base::FilePath() : context->GetPath(),
relative_partition_path, context->GetSpecialStoragePolicy());

partition->lock_manager_ = new LockManager();

base::FilePath path = in_memory ? base::FilePath() : partition_path;
partition->indexed_db_context_ = new IndexedDBContextImpl(
path, context->GetSpecialStoragePolicy(), quota_manager_proxy,
indexed_db::GetDefaultLevelDBFactory());

partition->cache_storage_context_ = new CacheStorageContextImpl(context);
partition->cache_storage_context_->Init(path, quota_manager_proxy);

partition->service_worker_context_ = new ServiceWorkerContextWrapper(context);
partition->service_worker_context_->set_storage_partition(partition.get());

partition->appcache_service_ =
base::MakeRefCounted<ChromeAppCacheService>(quota_manager_proxy.get());

partition->shared_worker_service_ = std::make_unique<SharedWorkerServiceImpl>(
partition.get(), partition->service_worker_context_,
partition->appcache_service_);

partition->push_messaging_context_ =
new PushMessagingContext(context, partition->service_worker_context_);

#if !defined(OS_ANDROID)
partition->host_zoom_level_context_ = new HostZoomLevelContext(
context->CreateZoomLevelDelegate(partition_path));
#endif  // !defined(OS_ANDROID)

partition->platform_notification_context_ =
new PlatformNotificationContextImpl(path, context,
partition->service_worker_context_);
partition->platform_notification_context_->Initialize();

partition->background_fetch_context_ =
base::MakeRefCounted<BackgroundFetchContext>(
context, partition->service_worker_context_,
partition->cache_storage_context_, quota_manager_proxy);

partition->background_sync_context_ =
base::MakeRefCounted<BackgroundSyncContext>();
partition->background_sync_context_->Init(partition->service_worker_context_);

partition->payment_app_context_ = new PaymentAppContextImpl();
partition->payment_app_context_->Init(partition->service_worker_context_);

partition->broadcast_channel_provider_ = new BroadcastChannelProvider();

partition->bluetooth_allowed_devices_map_ = new BluetoothAllowedDevicesMap();

scoped_refptr<ChromeBlobStorageContext> blob_context =
ChromeBlobStorageContext::GetFor(context);

partition->url_loader_factory_getter_ = new URLLoaderFactoryGetter();
partition->url_loader_factory_getter_->Initialize(partition.get());

partition->service_worker_context_->Init(
path, quota_manager_proxy.get(), context->GetSpecialStoragePolicy(),
blob_context.get(), partition->url_loader_factory_getter_.get());

partition->blob_registry_ =
BlobRegistryWrapper::Create(blob_context, partition->filesystem_context_);

partition->appcache_service_->set_url_loader_factory_getter(
partition->url_loader_factory_getter_.get());

partition->prefetch_url_loader_service_ =
base::MakeRefCounted<PrefetchURLLoaderService>();

partition->cookie_store_context_ = base::MakeRefCounted<CookieStoreContext>();
// Unit tests use the Initialize() callback to crash early if restoring the
// CookieManagerStore's state from ServiceWorkerStorage fails. Production and
// browser tests rely on CookieStoreManager's well-defined behavior when
// restoring the state fails.
partition->cookie_store_context_->Initialize(
partition->service_worker_context_, base::DoNothing());

if (base::FeatureList::IsEnabled(net::features::kIsolatedCodeCache)) {
GeneratedCodeCacheSettings settings =
GetContentClient()->browser()->GetGeneratedCodeCacheSettings(context);

// For Incognito mode, we should not persist anything on the disk so
// we do not create a code cache. Caching the generated code in memory
// is not useful, since V8 already maintains one copy in memory.
if (!in_memory && settings.enabled()) {
partition->generated_code_cache_context_ =
base::MakeRefCounted<GeneratedCodeCacheContext>();

base::FilePath code_cache_path;
if (partition_domain.empty()) {
code_cache_path = settings.path().AppendASCII("Code Cache");
} else {
// For site isolated partitions use the config directory.
code_cache_path = settings.path()
.Append(relative_partition_path)
.AppendASCII("Code Cache");
}
DCHECK_GE(settings.size_in_bytes(), 0);
partition->GetGeneratedCodeCacheContext()->Initialize(
code_cache_path, settings.size_in_bytes());
}
}

return partition;
}

void MediaStreamManager::CancelAllRequests(int render_process_id,
                                           int render_frame_id) {
DCHECK_CURRENTLY_ON(BrowserThread::IO);
auto request_it = requests_.begin();
while (request_it != requests_.end()) {
if (request_it->second->requesting_process_id != render_process_id ||
        request_it->second->requesting_frame_id != render_frame_id) {
++request_it;
continue;
}
const std::string label = request_it->first;
++request_it;
CancelRequest(label);
}
}

