// navigating it.  Either way, app tabs should be considered extension
// processes, but they have no elevated privileges and thus should not
// have WebUI bindings.
ui_test_utils::NavigateToURLWithDisposition(
browser(), base_url.Resolve("path1/empty.html"),
WindowOpenDisposition::NEW_FOREGROUND_TAB,
ui_test_utils::BROWSER_TEST_WAIT_FOR_NAVIGATION);
LOG(INFO) << "Nav 1.";
EXPECT_TRUE(process_map->Contains(
browser()->tab_strip_model()->GetWebContentsAt(1)->
GetRenderProcessHost()->GetID()));
EXPECT_FALSE(browser()->tab_strip_model()->GetWebContentsAt(1)->GetWebUI());

content::WindowedNotificationObserver tab_added_observer(
chrome::NOTIFICATION_TAB_ADDED,
content::NotificationService::AllSources());
chrome::NewTab(browser());
tab_added_observer.Wait();
LOG(INFO) << "New tab.";
ui_test_utils::NavigateToURL(browser(),
base_url.Resolve("path2/empty.html"));
LOG(INFO) << "Nav 2.";
EXPECT_TRUE(process_map->Contains(
browser()->tab_strip_model()->GetWebContentsAt(2)->
GetRenderProcessHost()->GetID()));
EXPECT_FALSE(browser()->tab_strip_model()->GetWebContentsAt(2)->GetWebUI());

// We should have opened 2 new extension tabs. Including the original blank
// tab, we now have 3 tabs. The two app tabs should not be in the same
// process, since they do not have the background permission.  (Thus, we
// want to separate them to improve responsiveness.)
ASSERT_EQ(3, browser()->tab_strip_model()->count());
WebContents* tab1 = browser()->tab_strip_model()->GetWebContentsAt(1);
WebContents* tab2 = browser()->tab_strip_model()->GetWebContentsAt(2);
EXPECT_NE(tab1->GetRenderProcessHost(), tab2->GetRenderProcessHost());

// Opening tabs with window.open should keep the page in the opener's
// process.
ASSERT_EQ(1u, chrome::GetBrowserCount(browser()->profile()));
    OpenWindow(tab1, base_url.Resolve("path1/empty.html"), true, NULL);
LOG(INFO) << "WindowOpenHelper 1.";
    OpenWindow(tab2, base_url.Resolve("path2/empty.html"), true, NULL);
LOG(INFO) << "End of test.";
UnloadExtension(extension->id());
}

long Cluster::HasBlockEntries(
const Segment* pSegment,
long long off,  // relative to start of segment payload
long long& pos, long& len) {
assert(pSegment);
assert(off >= 0); // relative to segment

IMkvReader* const pReader = pSegment->m_pReader;

long long total, avail;

long status = pReader->Length(&total, &avail);

if (status < 0) // error
return status;

assert((total < 0) || (avail <= total));

pos = pSegment->m_start + off; // absolute

if ((total >= 0) && (pos >= total))
return 0; // we don't even have a complete cluster

const long long segment_stop =
(pSegment->m_size < 0) ? -1 : pSegment->m_start + pSegment->m_size;

long long cluster_stop = -1; // interpreted later to mean "unknown size"

{
if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

long long result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // need more data
return E_BUFFER_NOT_FULL;

if ((segment_stop >= 0) && ((pos + len) > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((total >= 0) && ((pos + len) > total))
return 0;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long id = ReadUInt(pReader, pos, len);

if (id < 0) // error
return static_cast<long>(id);

if (id != 0x0F43B675) // weird: not cluster ID
return -1; // generic error

pos += len; // consume Cluster ID field

// read size field

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // weird
return E_BUFFER_NOT_FULL;

if ((segment_stop >= 0) && ((pos + len) > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((total >= 0) && ((pos + len) > total))
return 0;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long size = ReadUInt(pReader, pos, len);

if (size < 0) // error
return static_cast<long>(size);

if (size == 0)
return 0; // cluster does not have entries

pos += len; // consume size field

// pos now points to start of payload

const long long unknown_size = (1LL << (7 * len)) - 1;

if (size != unknown_size) {
cluster_stop = pos + size;
assert(cluster_stop >= 0);

if ((segment_stop >= 0) && (cluster_stop > segment_stop))
return E_FILE_FORMAT_INVALID;

if ((total >= 0) && (cluster_stop > total))
// return E_FILE_FORMAT_INVALID;  //too conservative
return 0; // cluster does not have any entries
}
}

for (;;) {
if ((cluster_stop >= 0) && (pos >= cluster_stop))
return 0; // no entries detected

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

long long result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // need more data
return E_BUFFER_NOT_FULL;

if ((cluster_stop >= 0) && ((pos + len) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long id = ReadUInt(pReader, pos, len);

if (id < 0) // error
return static_cast<long>(id);

// This is the distinguished set of ID's we use to determine
// that we have exhausted the sub-element's inside the cluster
// whose ID we parsed earlier.

if (id == 0x0F43B675) // Cluster ID
return 0; // no entries found

if (id == 0x0C53BB6B) // Cues ID
return 0; // no entries found

pos += len; // consume id field

if ((cluster_stop >= 0) && (pos >= cluster_stop))
return E_FILE_FORMAT_INVALID;

// read size field

if ((pos + 1) > avail) {
len = 1;
return E_BUFFER_NOT_FULL;
}

result = GetUIntLength(pReader, pos, len);

if (result < 0) // error
return static_cast<long>(result);

if (result > 0) // underflow
return E_BUFFER_NOT_FULL;

if ((cluster_stop >= 0) && ((pos + len) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if ((pos + len) > avail)
return E_BUFFER_NOT_FULL;

const long long size = ReadUInt(pReader, pos, len);

if (size < 0) // error
return static_cast<long>(size);

pos += len; // consume size field

// pos now points to start of payload

if ((cluster_stop >= 0) && (pos > cluster_stop))
return E_FILE_FORMAT_INVALID;

if (size == 0) // weird
continue;

const long long unknown_size = (1LL << (7 * len)) - 1;

if (size == unknown_size)
return E_FILE_FORMAT_INVALID; // not supported inside cluster

if ((cluster_stop >= 0) && ((pos + size) > cluster_stop))
return E_FILE_FORMAT_INVALID;

if (id == 0x20) // BlockGroup ID
return 1; // have at least one entry

if (id == 0x23) // SimpleBlock ID

return 1;  // have at least one entry

pos += size;  // consume payload
    assert((cluster_stop < 0) || (pos <= cluster_stop));
}
}

PP_Resource ResourceTracker::AddResource(Resource* resource) {
// If the plugin manages to create 1 billion resources, don't do crazy stuff.
if (last_resource_id_ ==
(std::numeric_limits<PP_Resource>::max() >> kPPIdTypeBits))
return 0;

// Add the resource with plugin use-count 1.
PP_Resource new_id = MakeTypedId(++last_resource_id_, PP_ID_TYPE_RESOURCE);
live_resources_.insert(std::make_pair(new_id, std::make_pair(resource, 1)));

// Track associated with the instance.
PP_Instance pp_instance = resource->instance()->pp_instance();
DCHECK(instance_map_.find(pp_instance) != instance_map_.end());
  instance_map_[pp_instance]->resources.insert(new_id);
return new_id;
}

Utterance::Utterance(Profile* profile,
                     const std::string& text,
                     DictionaryValue* options,
                     Task* completion_task)
    : profile_(profile),
      id_(next_utterance_id_++),
      text_(text),
      rate_(-1.0),
      pitch_(-1.0),
      volume_(-1.0),
      can_enqueue_(false),
      completion_task_(completion_task) {
  if (!options) {
    // Use all default options.
    options_.reset(new DictionaryValue());
    return;
}

  options_.reset(options->DeepCopy());
  if (options->HasKey(util::kVoiceNameKey))
    options->GetString(util::kVoiceNameKey, &voice_name_);
  if (options->HasKey(util::kLocaleKey))
    options->GetString(util::kLocaleKey, &locale_);
  if (options->HasKey(util::kGenderKey))
    options->GetString(util::kGenderKey, &gender_);
  if (options->GetDouble(util::kRateKey, &rate_)) {
    if (!base::IsFinite(rate_) || rate_ < 0.0 || rate_ > 1.0)
      rate_ = -1.0;
}

  if (options->GetDouble(util::kPitchKey, &pitch_)) {
    if (!base::IsFinite(pitch_) || pitch_ < 0.0 || pitch_ > 1.0)
      pitch_ = -1.0;
}

  if (options->GetDouble(util::kVolumeKey, &volume_)) {
    if (!base::IsFinite(volume_) || volume_ < 0.0 || volume_ > 1.0)
      volume_ = -1.0;
}

  if (options->HasKey(util::kEnqueueKey))
    options->GetBoolean(util::kEnqueueKey, &can_enqueue_);
}

