long ContentEncoding::ParseEncryptionEntry(
    long long start,
    long long size,
    IMkvReader* pReader,
    ContentEncryption* encryption) {
assert(pReader);
assert(encryption);

long long pos = start;
const long long stop = start + size;


while (pos < stop) {
long long id, size;
    const long status = ParseElementHeader(pReader,
                                           pos,
                                           stop,
                                           id,
                                           size);
    if (status < 0)  //error
return status;

if (id == 0x7E1) {
// ContentEncAlgo
encryption->algo = UnserializeUInt(pReader, pos, size);
if (encryption->algo != 5)

return E_FILE_FORMAT_INVALID;
} else if (id == 0x7E2) {
// ContentEncKeyID
      delete[] encryption->key_id;
encryption->key_id = NULL;
encryption->key_id_len = 0;

if (size <= 0)
return E_FILE_FORMAT_INVALID;

const size_t buflen = static_cast<size_t>(size);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];

if (buf == NULL)
return -1;

      const int read_status = pReader->Read(pos, buflen, buf);
if (read_status) {
        delete [] buf;
return status;
}

encryption->key_id = buf;

encryption->key_id_len = buflen;
} else if (id == 0x7E3) {
// ContentSignature
      delete[] encryption->signature;
encryption->signature = NULL;
encryption->signature_len = 0;

if (size <= 0)
return E_FILE_FORMAT_INVALID;

const size_t buflen = static_cast<size_t>(size);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];

if (buf == NULL)
return -1;

      const int read_status = pReader->Read(pos, buflen, buf);
if (read_status) {
        delete [] buf;
return status;
}

encryption->signature = buf;

encryption->signature_len = buflen;
} else if (id == 0x7E4) {
// ContentSigKeyID
      delete[] encryption->sig_key_id;
encryption->sig_key_id = NULL;
encryption->sig_key_id_len = 0;

if (size <= 0)
return E_FILE_FORMAT_INVALID;

const size_t buflen = static_cast<size_t>(size);
typedef unsigned char* buf_t;
const buf_t buf = new (std::nothrow) unsigned char[buflen];

if (buf == NULL)
return -1;

      const int read_status = pReader->Read(pos, buflen, buf);
if (read_status) {
        delete [] buf;
return status;
}

encryption->sig_key_id = buf;
encryption->sig_key_id_len = buflen;
} else if (id == 0x7E5) {
// ContentSigAlgo
encryption->sig_algo = UnserializeUInt(pReader, pos, size);
} else if (id == 0x7E6) {
// ContentSigHashAlgo
encryption->sig_hash_algo = UnserializeUInt(pReader, pos, size);

} else if (id == 0x7E7) {
// ContentEncAESSettings
const long status = ParseContentEncAESSettingsEntry(
          pos,
          size,
          pReader,
          &encryption->aes_settings);
if (status)
return status;
}

    pos += size;  //consume payload
assert(pos <= stop);
}

return 0;
}

static inline unsigned int ReadPropertyUnsignedLong(const EndianType endian,
const unsigned char *buffer)
{
unsigned int
value;

if (endian == LSBEndian)
{
      value=(unsigned int) ((buffer[3] << 24) | (buffer[2] << 16) |
        (buffer[1] << 8 ) | (buffer[0]));
      return((unsigned int) (value & 0xffffffff));
}
  value=(unsigned int) ((buffer[0] << 24) | (buffer[1] << 16) |
    (buffer[2] << 8) | buffer[3]);
  return((unsigned int) (value & 0xffffffff));
}

