static js_Ast *memberexp(js_State *J)
{
       js_Ast *a;
       INCREC();
       a = newexp(J);
loop:
if (jsP_accept(J, '.')) { a = EXP2(MEMBER, a, identifiername(J)); goto loop; }
if (jsP_accept(J, '[')) { a = EXP2(INDEX, a, expression(J, 0)); jsP_expect(J, ']'); goto loop; }
       DECREC();
return a;
}

valid_length(uint8_t option, int dl, int *type)
{
const struct dhcp_opt *opt;
ssize_t sz;

if (dl == 0)
return -1;

for (opt = dhcp_opts; opt->option; opt++) {
if (opt->option != option)
continue;


if (type)
*type = opt->type;
if (opt->type == 0 ||
opt->type & (STRING | RFC3442 | RFC5969))
return 0;
sz = 0;
		if (opt->type & (UINT32 | IPV4))
sz = sizeof(uint32_t);
		if (opt->type & UINT16)
sz = sizeof(uint16_t);
		if (opt->type & UINT8)
sz = sizeof(uint8_t);
		if (opt->type & (IPV4 | ARRAY))
			return dl % sz;
		return (dl == sz ? 0 : -1);
}

/* unknown option, so let it pass */
return 0;
}

