status_t BnHDCP::onTransact(
uint32_t code, const Parcel &data, Parcel *reply, uint32_t flags) {
switch (code) {
case HDCP_SET_OBSERVER:
{
CHECK_INTERFACE(IHDCP, data, reply);

sp<IHDCPObserver> observer =
interface_cast<IHDCPObserver>(data.readStrongBinder());

reply->writeInt32(setObserver(observer));
return OK;
}

case HDCP_INIT_ASYNC:
{
CHECK_INTERFACE(IHDCP, data, reply);

const char *host = data.readCString();
unsigned port = data.readInt32();

reply->writeInt32(initAsync(host, port));
return OK;
}

case HDCP_SHUTDOWN_ASYNC:
{
CHECK_INTERFACE(IHDCP, data, reply);

reply->writeInt32(shutdownAsync());
return OK;
}

case HDCP_GET_CAPS:
{
CHECK_INTERFACE(IHDCP, data, reply);

reply->writeInt32(getCaps());
return OK;
}


case HDCP_ENCRYPT:
{
size_t size = data.readInt32();
            size_t bufSize = 2 * size;
            // watch out for overflow
void *inData = NULL;
            if (bufSize > size) {
                inData = malloc(bufSize);
}
if (inData == NULL) {
reply->writeInt32(ERROR_OUT_OF_RANGE);
return OK;
}


void *outData = (uint8_t *)inData + size;

            data.read(inData, size);

uint32_t streamCTR = data.readInt32();
uint64_t inputCTR;
            status_t err = encrypt(inData, size, streamCTR, &inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->writeInt64(inputCTR);
reply->write(outData, size);
}

free(inData);
inData = outData = NULL;

return OK;
}

case HDCP_ENCRYPT_NATIVE:
{
CHECK_INTERFACE(IHDCP, data, reply);

sp<GraphicBuffer> graphicBuffer = new GraphicBuffer();
data.read(*graphicBuffer);
size_t offset = data.readInt32();
size_t size = data.readInt32();
uint32_t streamCTR = data.readInt32();
void *outData = malloc(size);
uint64_t inputCTR;

status_t err = encryptNative(graphicBuffer, offset, size,
streamCTR, &inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->writeInt64(inputCTR);
reply->write(outData, size);
}

free(outData);
outData = NULL;

return OK;
}

case HDCP_DECRYPT:
{
size_t size = data.readInt32();
size_t bufSize = 2 * size;

// watch out for overflow
void *inData = NULL;
if (bufSize > size) {
inData = malloc(bufSize);
}

if (inData == NULL) {
reply->writeInt32(ERROR_OUT_OF_RANGE);
return OK;
}

void *outData = (uint8_t *)inData + size;

data.read(inData, size);

uint32_t streamCTR = data.readInt32();
uint64_t inputCTR = data.readInt64();
status_t err = decrypt(inData, size, streamCTR, inputCTR, outData);

reply->writeInt32(err);

if (err == OK) {
reply->write(outData, size);
}

free(inData);
inData = outData = NULL;

return OK;
}

default:
return BBinder::onTransact(code, data, reply, flags);
}
}

struct sock *tcp_v4_syn_recv_sock(struct sock *sk, struct sk_buff *skb,
struct request_sock *req,
struct dst_entry *dst)
{
struct inet_request_sock *ireq;
struct inet_sock *newinet;
struct tcp_sock *newtp;
struct sock *newsk;
#ifdef CONFIG_TCP_MD5SIG
struct tcp_md5sig_key *key;
#endif

if (sk_acceptq_is_full(sk))
goto exit_overflow;

if (!dst && (dst = inet_csk_route_req(sk, req)) == NULL)
goto exit;

newsk = tcp_create_openreq_child(sk, req, skb);
if (!newsk)
goto exit_nonewsk;

newsk->sk_gso_type = SKB_GSO_TCPV4;
sk_setup_caps(newsk, dst);

newtp		      = tcp_sk(newsk);
newinet		      = inet_sk(newsk);
ireq		      = inet_rsk(req);
newinet->inet_daddr   = ireq->rmt_addr;
newinet->inet_rcv_saddr = ireq->loc_addr;
newinet->inet_saddr	      = ireq->loc_addr;
	newinet->opt	      = ireq->opt;
ireq->opt	      = NULL;
newinet->mc_index     = inet_iif(skb);
newinet->mc_ttl	      = ip_hdr(skb)->ttl;
inet_csk(newsk)->icsk_ext_hdr_len = 0;
	if (newinet->opt)
		inet_csk(newsk)->icsk_ext_hdr_len = newinet->opt->optlen;
newinet->inet_id = newtp->write_seq ^ jiffies;

tcp_mtup_init(newsk);
tcp_sync_mss(newsk, dst_mtu(dst));
newtp->advmss = dst_metric_advmss(dst);
if (tcp_sk(sk)->rx_opt.user_mss &&
tcp_sk(sk)->rx_opt.user_mss < newtp->advmss)
newtp->advmss = tcp_sk(sk)->rx_opt.user_mss;

tcp_initialize_rcv_mss(newsk);

#ifdef CONFIG_TCP_MD5SIG
/* Copy over the MD5 key from the original socket */
key = tcp_v4_md5_do_lookup(sk, newinet->inet_daddr);
if (key != NULL) {
/*
* We're using one, so create a matching key
* on the newsk structure. If we fail to get
* memory, then we end up not copying the key
* across. Shucks.
*/
char *newkey = kmemdup(key->key, key->keylen, GFP_ATOMIC);
if (newkey != NULL)
tcp_v4_md5_do_add(newsk, newinet->inet_daddr,
newkey, key->keylen);
sk_nocaps_add(newsk, NETIF_F_GSO_MASK);
}
#endif

if (__inet_inherit_port(sk, newsk) < 0) {
sock_put(newsk);
goto exit;
}
__inet_hash_nolisten(newsk, NULL);

return newsk;

exit_overflow:
NET_INC_STATS_BH(sock_net(sk), LINUX_MIB_LISTENOVERFLOWS);
exit_nonewsk:
dst_release(dst);
exit:
NET_INC_STATS_BH(sock_net(sk), LINUX_MIB_LISTENDROPS);
return NULL;
}

long Chapters::Atom::Parse(IMkvReader* pReader, long long pos, long long size) {
const long long stop = pos + size;

while (pos < stop) {
long long id, size;

long status = ParseElementHeader(pReader, pos, stop, id, size);

if (status < 0) // error
return status;

if (size == 0) // weird
continue;

if (id == 0x00) { // Display ID
status = ParseDisplay(pReader, pos, size);

if (status < 0) // error
return status;
} else if (id == 0x1654) { // StringUID ID
status = UnserializeString(pReader, pos, size, m_string_uid);

if (status < 0) // error
return status;
} else if (id == 0x33C4) { // UID ID
long long val;
status = UnserializeInt(pReader, pos, size, val);

if (status < 0) // error
return status;

m_uid = static_cast<unsigned long long>(val);
} else if (id == 0x11) { // TimeStart ID
const long long val = UnserializeUInt(pReader, pos, size);

if (val < 0) // error
return static_cast<long>(val);

m_start_timecode = val;
} else if (id == 0x12) { // TimeEnd ID
const long long val = UnserializeUInt(pReader, pos, size);

if (val < 0) // error
return static_cast<long>(val);

m_stop_timecode = val;

}

pos += size;
    assert(pos <= stop);
}

  assert(pos == stop);
return 0;
}

