if ((segment_stop >= 0) && ((pos + size) > segment_stop)) //weird
return E_FILE_FORMAT_INVALID;

pos += size; //consume payload of sub-element
assert((segment_stop < 0) || (pos <= segment_stop));
} //determine cluster size

cluster_size = pos - payload_pos;
assert(cluster_size >= 0);

pos = payload_pos; //reset and re-parse original cluster
}

if (m_clusterPreloadCount > 0)
{
assert(idx < m_clusterSize);

Cluster* const pCluster = m_clusters[idx];
assert(pCluster);
assert(pCluster->m_index < 0);

const long long off = pCluster->GetPosition();
assert(off >= 0);

if (off == cluster_off) //preloaded already
return E_FILE_FORMAT_INVALID; //subtle
}

m_pos = pos + cluster_size; //consume payload
assert((segment_stop < 0) || (m_pos <= segment_stop));


return 2;     //try to find another cluster

#endif
}

bool SelectFileDialogImpl::RunOpenFileDialog(
const std::wstring& title,
const std::wstring& filter,
HWND owner,
FilePath* path) {
OPENFILENAME ofn;
// We must do this otherwise the ofn's FlagsEx may be initialized to random
// junk in release builds which can cause the Places Bar not to show up!
ZeroMemory(&ofn, sizeof(ofn));
ofn.lStructSize = sizeof(ofn);
ofn.hwndOwner = owner;

wchar_t filename[MAX_PATH];
// According to http://support.microsoft.com/?scid=kb;en-us;222003&x=8&y=12,
// The lpstrFile Buffer MUST be NULL Terminated.
filename[0] = 0;
// Define the dir in here to keep the string buffer pointer pointed to
// ofn.lpstrInitialDir available during the period of running the
// GetOpenFileName.
FilePath dir;
// Use lpstrInitialDir to specify the initial directory
if (!path->empty()) {
bool is_dir;
base::PlatformFileInfo file_info;
if (file_util::GetFileInfo(*path, &file_info))
is_dir = file_info.is_directory;
else
is_dir = file_util::EndsWithSeparator(*path);
if (is_dir) {
ofn.lpstrInitialDir = path->value().c_str();
} else {
dir = path->DirName();
ofn.lpstrInitialDir = dir.value().c_str();
// Only pure filename can be put in lpstrFile field.
base::wcslcpy(filename, path->BaseName().value().c_str(),
arraysize(filename));
}
}

ofn.lpstrFile = filename;
ofn.nMaxFile = MAX_PATH;

// We use OFN_NOCHANGEDIR so that the user can rename or delete the directory
// without having to close Chrome first.
ofn.Flags = OFN_FILEMUSTEXIST | OFN_NOCHANGEDIR;

if (!filter.empty())
ofn.lpstrFilter = filter.c_str();
  bool success = !!GetOpenFileName(&ofn);
DisableOwner(owner);
if (success)
*path = FilePath(filename);
return success;
}

static gboolean cosine_read(wtap *wth, int *err, gchar **err_info,
gint64 *data_offset)
{
gint64	offset;
	int	pkt_len;
char	line[COSINE_LINE_LENGTH];

/* Find the next packet */
offset = cosine_seek_next_packet(wth, err, err_info, line);
if (offset < 0)
return FALSE;
*data_offset = offset;

	/* Parse the header *
	pkt_len = parse_cosine_rec_hdr(&wth->phdr, line, err, err_info);
	if (pkt_len == -1)
		return FALSE;
	/* Convert the ASCII hex dump to binary data *
	return parse_cosine_hex_dump(wth->fh, &wth->phdr, pkt_len,
	    wth->frame_buffer, err, err_info);
}

