CPError CPB_GetCommandLineArgumentsCommon(const char* url,
std::string* arguments) {
const CommandLine cmd = *CommandLine::ForCurrentProcess();
std::wstring arguments_w;

// Use the same UserDataDir for new launches that we currently have set.
std::wstring user_data_dir = cmd.GetSwitchValue(switches::kUserDataDir);
if (!user_data_dir.empty()) {
// Make sure user_data_dir is an absolute path.
if (file_util::AbsolutePath(&user_data_dir) &&
file_util::PathExists(FilePath::FromWStringHack(user_data_dir))) {
// TODO(evanm): use CommandLine APIs instead of this.
arguments_w += std::wstring(L"--") + ASCIIToWide(switches::kUserDataDir) +
L"=\"" + user_data_dir + L"\" ";
}
}

#if defined (OS_CHROMEOS)
std::wstring profile = cmd.GetSwitchValue(switches::kProfile);
if (!profile.empty()) {
arguments_w += std::wstring(L"--") + ASCIIToWide(switches::kProfile) +
L"=\"" + profile + L"\" ";
}
#endif

// Use '--app=url' instead of just 'url' to launch the browser with minimal
// chrome.
// Note: Do not change this flag!  Old Gears shortcuts will break if you do!
std::string url_string(url);
  ReplaceSubstringsAfterOffset(&url_string, 0, "\"", "\\\"");
  ReplaceSubstringsAfterOffset(&url_string, 0, "%", "%%");
  ReplaceSubstringsAfterOffset(&url_string, 0, ";", "");
  ReplaceSubstringsAfterOffset(&url_string, 0, "$", "");
std::wstring url_w = UTF8ToWide(url_string);
// TODO(evanm): use CommandLine APIs instead of this.
arguments_w += std::wstring(L"--") + ASCIIToWide(switches::kApp) +
L"=\"" + url_w + L"\"";

*arguments = WideToUTF8(arguments_w);

return CPERR_SUCCESS;
}

void FragmentPaintPropertyTreeBuilder::UpdateInnerBorderRadiusClip() {
DCHECK(properties_);

if (NeedsPaintPropertyUpdate()) {
if (NeedsInnerBorderRadiusClip(object_)) {
const LayoutBox& box = ToLayoutBox(object_);
ClipPaintPropertyNode::State state;
state.local_transform_space = context_.current.transform;
if (box.IsLayoutReplaced()) {
// LayoutReplaced clips the foreground by rounded inner content box.
state.clip_rect = box.StyleRef().GetRoundedInnerBorderFor(
LayoutRect(context_.current.paint_offset, box.Size()),
LayoutRectOutsets(-(box.PaddingTop() + box.BorderTop()),
-(box.PaddingRight() + box.BorderRight()),
-(box.PaddingBottom() + box.BorderBottom()),
-(box.PaddingLeft() + box.BorderLeft())));
} else {
state.clip_rect = box.StyleRef().GetRoundedInnerBorderFor(
LayoutRect(context_.current.paint_offset, box.Size()));
}
OnUpdateClip(properties_->UpdateInnerBorderRadiusClip(
          context_.current.clip, std::move(state)));
} else {
OnClearClip(properties_->ClearInnerBorderRadiusClip());
}
}

if (auto* border_radius_clip = properties_->InnerBorderRadiusClip())
context_.current.clip = border_radius_clip;
}

