void CuePoint::Load(IMkvReader* pReader) {
// odbgstream os;
// os << "CuePoint::Load(begin): timecode=" << m_timecode << endl;

if (m_timecode >= 0)  // already loaded
    return;

assert(m_track_positions == NULL);
assert(m_track_positions_count == 0);

long long pos_ = -m_timecode;
const long long element_start = pos_;

long long stop;


{
long len;

    const long long id = ReadUInt(pReader, pos_, len);
    assert(id == 0x3B);  // CuePoint ID
if (id != 0x3B)
      return;

pos_ += len;  // consume ID

const long long size = ReadUInt(pReader, pos_, len);
assert(size >= 0);

pos_ += len; // consume Size field
// pos_ now points to start of payload

stop = pos_ + size;
}

const long long element_size = stop - element_start;

long long pos = pos_;

// First count number of track positions


while (pos < stop) {
long len;

    const long long id = ReadUInt(pReader, pos, len);
    assert(id >= 0);  // TODO
    assert((pos + len) <= stop);

pos += len;  // consume ID

const long long size = ReadUInt(pReader, pos, len);
    assert(size >= 0);
    assert((pos + len) <= stop);

pos += len;  // consume Size field
    assert((pos + size) <= stop);

if (id == 0x33)  // CueTime ID
m_timecode = UnserializeUInt(pReader, pos, size);

else if (id == 0x37) // CueTrackPosition(s) ID

++m_track_positions_count;

pos += size;  // consume payload
    assert(pos <= stop);
}

  assert(m_timecode >= 0);
  assert(m_track_positions_count > 0);

// os << "CuePoint::Load(cont'd): idpos=" << idpos
//   << " timecode=" << m_timecode
//   << endl;

  m_track_positions = new TrackPosition[m_track_positions_count];

// Now parse track positions

TrackPosition* p = m_track_positions;
pos = pos_;


while (pos < stop) {
long len;

    const long long id = ReadUInt(pReader, pos, len);
    assert(id >= 0);  // TODO
    assert((pos + len) <= stop);

pos += len;  // consume ID

const long long size = ReadUInt(pReader, pos, len);
assert(size >= 0);
assert((pos + len) <= stop);

pos += len; // consume Size field
assert((pos + size) <= stop);


if (id == 0x37) {  // CueTrackPosition(s) ID
TrackPosition& tp = *p++;
      tp.Parse(pReader, pos, size);
}

pos += size;  // consume payload
    assert(pos <= stop);
}

assert(size_t(p - m_track_positions) == m_track_positions_count);

m_element_start = element_start;
m_element_size = element_size;
}

static int snd_seq_ioctl_create_port(struct snd_seq_client *client, void *arg)
{
struct snd_seq_port_info *info = arg;
struct snd_seq_client_port *port;
struct snd_seq_port_callback *callback;

/* it is not allowed to create the port for an another client */
if (info->addr.client != client->number)
return -EPERM;

port = snd_seq_create_port(client, (info->flags & SNDRV_SEQ_PORT_FLG_GIVEN_PORT) ? info->addr.port : -1);
if (port == NULL)
return -ENOMEM;

if (client->type == USER_CLIENT && info->kernel) {
		snd_seq_delete_port(client, port->addr.port);
return -EINVAL;
}
if (client->type == KERNEL_CLIENT) {
if ((callback = info->kernel) != NULL) {
if (callback->owner)
port->owner = callback->owner;
port->private_data = callback->private_data;
port->private_free = callback->private_free;
port->event_input = callback->event_input;
port->c_src.open = callback->subscribe;
port->c_src.close = callback->unsubscribe;
port->c_dest.open = callback->use;
port->c_dest.close = callback->unuse;
}
}

info->addr = port->addr;

snd_seq_set_port_info(port, info);
snd_seq_system_client_ev_port_start(port->addr.client, port->addr.port);

return 0;
}

void get_checksum2(char *buf, int32 len, char *sum)
{
md_context m;

switch (xfersum_type) {
case CSUM_MD5: {
uchar seedbuf[4];
md5_begin(&m);
if (proper_seed_order) {
if (checksum_seed) {
SIVALu(seedbuf, 0, checksum_seed);
md5_update(&m, seedbuf, 4);
}
md5_update(&m, (uchar *)buf, len);
} else {
md5_update(&m, (uchar *)buf, len);
if (checksum_seed) {
SIVALu(seedbuf, 0, checksum_seed);
md5_update(&m, seedbuf, 4);
}
}
md5_result(&m, (uchar *)sum);
break;
}
case CSUM_MD4:
case CSUM_MD4_OLD:
         case CSUM_MD4_BUSTED: {
int32 i;
static char *buf1;
static int32 len1;
mdfour_begin(&m);

if (len > len1) {
if (buf1)
free(buf1);
buf1 = new_array(char, len+4);
len1 = len;
if (!buf1)
out_of_memory("get_checksum2");
}

memcpy(buf1, buf, len);
if (checksum_seed) {
SIVAL(buf1,len,checksum_seed);
len += 4;
}

for (i = 0; i + CSUM_CHUNK <= len; i += CSUM_CHUNK)
mdfour_update(&m, (uchar *)(buf1+i), CSUM_CHUNK);

/*
* Prior to version 27 an incorrect MD4 checksum was computed
* by failing to call mdfour_tail() for block sizes that
* are multiples of 64.  This is fixed by calling mdfour_update()
* are multiples of 64.  This is fixed by calling mdfour_update()
* even when there are no more bytes.
*/
               if (len - i > 0 || xfersum_type != CSUM_MD4_BUSTED)
mdfour_update(&m, (uchar *)(buf1+i), len-i);

mdfour_result(&m, (uchar *)sum);
}
}
}

int _dbus_printf_string_upper_bound (const char *format,
va_list args)
{
/* MSVCRT's vsnprintf semantics are a bit different */
char buf[1024];
int bufsize;
int len;

bufsize = sizeof (buf);
  len = _vsnprintf (buf, bufsize - 1, format, args);

while (len == -1) /* try again */
{

p = malloc (bufsize);

if (p == NULL)
return -1;

if (p == NULL)
return -1;

      len = _vsnprintf (p, bufsize - 1, format, args);
free (p);
}
* Returns the UTF-16 form of a UTF-8 string. The result should be
* freed with dbus_free() when no longer needed.
*
* @param str the UTF-8 string
* @param error return location for error code
*/
wchar_t *
_dbus_win_utf8_to_utf16 (const char *str,
DBusError  *error)
{
DBusString s;
int n;
wchar_t *retval;

_dbus_string_init_const (&s, str);

if (!_dbus_string_validate_utf8 (&s, 0, _dbus_string_get_length (&s)))
{
dbus_set_error_const (error, DBUS_ERROR_FAILED, "Invalid UTF-8");
return NULL;
}

n = MultiByteToWideChar (CP_UTF8, 0, str, -1, NULL, 0);

if (n == 0)
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
return NULL;
}

retval = dbus_new (wchar_t, n);

if (!retval)
{
_DBUS_SET_OOM (error);
return NULL;
}

if (MultiByteToWideChar (CP_UTF8, 0, str, -1, retval, n) != n)
{
dbus_free (retval);
dbus_set_error_const (error, DBUS_ERROR_FAILED, "MultiByteToWideChar inconsistency");
return NULL;
}

return retval;
}

/**
* Returns the UTF-8 form of a UTF-16 string. The result should be
* freed with dbus_free() when no longer needed.
*
* @param str the UTF-16 string
* @param error return location for error code
*/
char *
_dbus_win_utf16_to_utf8 (const wchar_t *str,
DBusError     *error)
{
int n;
char *retval;

n = WideCharToMultiByte (CP_UTF8, 0, str, -1, NULL, 0, NULL, NULL);

if (n == 0)
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
return NULL;
}

retval = dbus_malloc (n);

if (!retval)
{
_DBUS_SET_OOM (error);
return NULL;
}

if (WideCharToMultiByte (CP_UTF8, 0, str, -1, retval, n, NULL, NULL) != n)
{
dbus_free (retval);
dbus_set_error_const (error, DBUS_ERROR_FAILED, "WideCharToMultiByte inconsistency");
return NULL;
}

return retval;
}






/************************************************************************


************************************************************************/

dbus_bool_t
_dbus_win_account_to_sid (const wchar_t *waccount,
void      	 **ppsid,
DBusError 	  *error)
{
dbus_bool_t retval = FALSE;
DWORD sid_length, wdomain_length;
SID_NAME_USE use;
wchar_t *wdomain;

*ppsid = NULL;

sid_length = 0;
wdomain_length = 0;
if (!LookupAccountNameW (NULL, waccount, NULL, &sid_length,
NULL, &wdomain_length, &use) &&
GetLastError () != ERROR_INSUFFICIENT_BUFFER)
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
return FALSE;
}

*ppsid = dbus_malloc (sid_length);
if (!*ppsid)
{
_DBUS_SET_OOM (error);
return FALSE;
}

wdomain = dbus_new (wchar_t, wdomain_length);
if (!wdomain)
{
_DBUS_SET_OOM (error);
goto out1;
}

if (!LookupAccountNameW (NULL, waccount, (PSID) *ppsid, &sid_length,
wdomain, &wdomain_length, &use))
{
_dbus_win_set_error_from_win_error (error, GetLastError ());
goto out2;
}

if (!IsValidSid ((PSID) *ppsid))
{
dbus_set_error_const (error, DBUS_ERROR_FAILED, "Invalid SID");
goto out2;
}

retval = TRUE;

out2:
dbus_free (wdomain);
out1:
if (!retval)
{
dbus_free (*ppsid);
*ppsid = NULL;
}

return retval;
}

