ScriptPromise BluetoothRemoteGATTServer::getPrimaryServicesImpl(
ScriptState* scriptState,
mojom::blink::WebBluetoothGATTQueryQuantity quantity,
String servicesUUID) {
// We always check that the device is connected.
if (!connected()) {
return ScriptPromise::rejectWithDOMException(
scriptState,
DOMException::create(NetworkError, kGATTServerNotConnected));
}

ScriptPromiseResolver* resolver = ScriptPromiseResolver::create(scriptState);
ScriptPromise promise = resolver->promise();
AddToActiveAlgorithms(resolver);

mojom::blink::WebBluetoothService* service = m_device->bluetooth()->service();
  WTF::Optional<String> uuid = WTF::nullopt;
  if (!servicesUUID.isEmpty())
    uuid = servicesUUID;
service->RemoteServerGetPrimaryServices(
      device()->id(), quantity, uuid,
convertToBaseCallback(
WTF::bind(&BluetoothRemoteGATTServer::GetPrimaryServicesCallback,
wrapPersistent(this), quantity, wrapPersistent(resolver))));
return promise;
}

bool SessionModelAssociator::UpdateAssociationsFromSyncModel(
const sync_api::ReadNode& root,
const sync_api::BaseTransaction* trans) {
DCHECK(CalledOnValidThread());

// Iterate through the nodes and associate any foreign sessions.
int64 id = root.GetFirstChildId();
while (id != sync_api::kInvalidId) {
sync_api::ReadNode sync_node(trans);
if (!sync_node.InitByIdLookup(id)) {
LOG(ERROR) << "Failed to fetch sync node for id " << id;
return false;
}

const sync_pb::SessionSpecifics& specifics =
sync_node.GetSessionSpecifics();
    const base::Time& modification_time = sync_node.GetModificationTime();
if (specifics.session_tag() != GetCurrentMachineTag()) {
if (!AssociateForeignSpecifics(specifics, modification_time)) {
return false;
}
} else if (id != local_session_syncid_) {
// This is previously stored local session information.
if (specifics.has_header()) {
if (sync_api::kInvalidId != local_session_syncid_)
return false;

// This is our previous header node, reuse it.
local_session_syncid_ = id;
if (specifics.header().has_client_name()) {
current_session_name_ = specifics.header().client_name();
}
} else {
if (!specifics.has_tab())
return false;

// This is a tab node. We want to track these to reuse them in our free
// tab node pool. They will be overwritten eventually, so need to do
// anything else.
tab_pool_.AddTabNode(id);
}
}

id = sync_node.GetSuccessorId();
}

// After updating from sync model all tabid's should be free.
if (!tab_pool_.full())
return false;

return true;
}

IceGenerateMagicCookie (
int len
)
{
    char    *auth;
#ifndef HAVE_ARC4RANDOM_BUF
long    ldata[2];
int	    seed;
int	    value;
int	    i;
#endif

    if ((auth = malloc (len + 1)) == NULL)
	return (NULL);
#ifdef HAVE_ARC4RANDOM_BUF
    arc4random_buf(auth, len);
#else
#ifdef ITIMER_REAL
{
struct timeval  now;
int	    i;
ldata[0] = now.tv_sec;
ldata[1] = now.tv_usec;
}
#else
{
long    time ();
ldata[0] = time ((long *) 0);
ldata[1] = getpid ();
}
#endif
seed = (ldata[0]) + (ldata[1] << 16);
srand (seed);
for (i = 0; i < len; i++)
ldata[1] = now.tv_usec;
value = rand ();
auth[i] = value & 0xff;
}

static int load_script(struct linux_binprm *bprm)
{
const char *i_arg, *i_name;
char *cp;
struct file *file;
char interp[BINPRM_BUF_SIZE];
int retval;

if ((bprm->buf[0] != '#') || (bprm->buf[1] != '!'))
return -ENOEXEC;
/*
* This section does the #! interpretation.
* Sorta complicated, but hopefully it will work.  -TYT
*/

allow_write_access(bprm->file);
fput(bprm->file);
bprm->file = NULL;

bprm->buf[BINPRM_BUF_SIZE - 1] = '\0';
if ((cp = strchr(bprm->buf, '\n')) == NULL)
cp = bprm->buf+BINPRM_BUF_SIZE-1;
*cp = '\0';
while (cp > bprm->buf) {
cp--;
if ((*cp == ' ') || (*cp == '\t'))
*cp = '\0';
else
break;
}
for (cp = bprm->buf+2; (*cp == ' ') || (*cp == '\t'); cp++);
if (*cp == '\0')
return -ENOEXEC; /* No interpreter name found */
i_name = cp;
i_arg = NULL;
for ( ; *cp && (*cp != ' ') && (*cp != '\t'); cp++)
/* nothing */ ;
while ((*cp == ' ') || (*cp == '\t'))
*cp++ = '\0';
if (*cp)
i_arg = cp;
strcpy (interp, i_name);
/*
* OK, we've parsed out the interpreter name and
* (optional) argument.
* Splice in (1) the interpreter's name for argv[0]
*           (2) (optional) argument to interpreter
*           (3) filename of shell script (replace argv[0])
*
* This is done in reverse order, because of how the
* user environment and arguments are stored.
*/
retval = remove_arg_zero(bprm);
if (retval)
return retval;
retval = copy_strings_kernel(1, &bprm->interp, bprm);
if (retval < 0) return retval;
bprm->argc++;
if (i_arg) {
retval = copy_strings_kernel(1, &i_arg, bprm);
if (retval < 0) return retval;
bprm->argc++;
}
retval = copy_strings_kernel(1, &i_name, bprm);
if (retval) return retval;
bprm->argc++;
	bprm->interp = interp;

/*
* OK, now restart the process with the interpreter's dentry.
*/
file = open_exec(interp);
if (IS_ERR(file))
return PTR_ERR(file);

bprm->file = file;
retval = prepare_binprm(bprm);
if (retval < 0)
return retval;
return search_binary_handler(bprm);
}

image_size_of_type(int color_type, int bit_depth, unsigned int *colors)
{
