static void php_zip_get_from(INTERNAL_FUNCTION_PARAMETERS, int type) /* {{{ */
{
struct zip *intern;
zval *self = getThis();

struct zip_stat sb;
struct zip_file *zf;

zend_long index = -1;
zend_long flags = 0;
zend_long len = 0;

zend_string *filename;
zend_string *buffer;

