            ps_dec->u4_bitoffset = ih264d_read_mmco_commands(ps_dec);
else
ps_bitstrm->u4_ofst += ps_dec->u4_bitoffset;

}
/* G050 */

if(ps_pps->u1_entropy_coding_mode == CABAC)
{
