void ClipboardWin::OnClipboardUpdate() {
DCHECK(window_);

if (::IsClipboardFormatAvailable(CF_UNICODETEXT)) {
base::string16 text;
// Add a scope, so that we keep the clipboard open for as short a time as
// possible.
{
ScopedClipboard clipboard;
if (!clipboard.Init(window_->hwnd())) {
LOG(WARNING) << "Couldn't open the clipboard." << GetLastError();
return;
}

HGLOBAL text_global = clipboard.GetData(CF_UNICODETEXT);
if (!text_global) {
LOG(WARNING) << "Couldn't get data from the clipboard: "
<< GetLastError();
return;
}

      base::win::ScopedHGlobal<WCHAR> text_lock(text_global);
if (!text_lock.get()) {
LOG(WARNING) << "Couldn't lock clipboard data: " << GetLastError();
return;
}
text.assign(text_lock.get());
}

protocol::ClipboardEvent event;
event.set_mime_type(kMimeTypeTextUtf8);
event.set_data(ReplaceCrLfByLf(base::UTF16ToUTF8(text)));

if (client_clipboard_.get()) {
client_clipboard_->InjectClipboardEvent(event);
}
}
}

long Track::Seek(
    long long time_ns,
    const BlockEntry*& pResult) const
{
    const long status = GetFirst(pResult);

    if (status < 0)  //buffer underflow, etc
        return status;

    assert(pResult);

    if (pResult->EOS())
        return 0;

    const Cluster* pCluster = pResult->GetCluster();
assert(pCluster);
assert(pCluster->GetIndex() >= 0);

    if (time_ns <= pResult->GetBlock()->GetTime(pCluster))
        return 0;

    Cluster** const clusters = m_pSegment->m_clusters;
    assert(clusters);

    const long count = m_pSegment->GetCount();  //loaded only, not preloaded
    assert(count > 0);

    Cluster** const i = clusters + pCluster->GetIndex();
    assert(i);
    assert(*i == pCluster);
assert(pCluster->GetTime() <= time_ns);

    Cluster** const j = clusters + count;

    Cluster** lo = i;
    Cluster** hi = j;

    while (lo < hi)
    {
        //INVARIANT:
        //[i, lo) <= time_ns
        //[lo, hi) ?
        //[hi, j)  > time_ns

        Cluster** const mid = lo + (hi - lo) / 2;
        assert(mid < hi);
        pCluster = *mid;
        assert(pCluster);
        assert(pCluster->GetIndex() >= 0);
        assert(pCluster->GetIndex() == long(mid - m_pSegment->m_clusters));
        const long long t = pCluster->GetTime();
        if (t <= time_ns)
            lo = mid + 1;
        else
            hi = mid;
        assert(lo <= hi);
    }
    assert(lo == hi);
    assert(lo > i);
    assert(lo <= j);
    while (lo > i)
    {
        pCluster = *--lo;
        assert(pCluster);
        assert(pCluster->GetTime() <= time_ns);
        pResult = pCluster->GetEntry(this);
        if ((pResult != 0) && !pResult->EOS())
            return 0;
        //landed on empty cluster (no entries)
    }
    pResult = GetEOS();  //weird
    return 0;
}

