bool PermissionsData::CanCaptureVisiblePage(const GURL& document_url,
                                            int tab_id,
                                            std::string* error) const {
bool has_active_tab = false;
bool has_all_urls = false;
// Check the real origin, in order to account for filesystem:, blob:, etc.
// (url::Origin grabs the inner origin of these, whereas GURL::GetOrigin()
// does not.)
url::Origin origin = url::Origin::Create(document_url);
const GURL origin_url = origin.GetURL();
{
base::AutoLock auto_lock(runtime_lock_);
// Disallow capturing policy-blocked hosts. No exceptions.
// Note: This isn't foolproof, since an extension could embed a policy-
// blocked host in a different page and then capture that, but it's better
// than nothing (and policy hosts can set their x-frame options
// accordingly).
if (location_ != Manifest::COMPONENT &&
IsPolicyBlockedHostUnsafe(origin_url)) {
if (error)
*error = extension_misc::kPolicyBlockedScripting;
return false;
}

const PermissionSet* tab_permissions = GetTabSpecificPermissions(tab_id);
has_active_tab = tab_permissions &&
tab_permissions->HasAPIPermission(APIPermission::kTab);

const URLPattern all_urls(URLPattern::SCHEME_ALL,
URLPattern::kAllUrlsPattern);
has_all_urls =
active_permissions_unsafe_->explicit_hosts().ContainsPattern(all_urls);
}

  // At least one of activeTab or <all_urls> is always required; no exceptions.
  if (!has_active_tab && !has_all_urls) {
    if (error)
      *error = manifest_errors::kAllURLOrActiveTabNeeded;
    return false;
  }

  // We check GetPageAccess() (in addition to the <all_urls> and activeTab
  // checks below) for the case of URLs that can be conditionally granted (such
  // as file:// URLs or chrome:// URLs for component extensions).
  // If an extension has <all_urls>, GetPageAccess() will still (correctly)
  // return false if, for instance, the URL is a file:// URL and the extension
  // does not have file access.
  // See https://crbug.com/810220.
  // If the extension has page access (and has activeTab or <all_urls>, as
  // checked above), allow the capture.
  std::string access_error;
  if (GetPageAccess(origin_url, tab_id, &access_error) == PageAccess::kAllowed)
    return true;

// The extension doesn't have explicit page access. However, there are a
// number of cases where tab capture may still be allowed.

// First special case: an extension's own pages.
// These aren't restricted URLs, but won't be matched by <all_urls> or
  // activeTab (since the extension scheme is not included in the list of valid
  // schemes for extension permissions).
  // To capture an extension's own page, either activeTab or <all_urls> is
  // needed (it's no higher privilege than a normal web page). At least one
  // of these is still needed because the extension page may have embedded
  // web content.
// TODO(devlin): Should activeTab/<all_urls> account for the extension's own
// domain?
if (origin_url.host() == extension_id_)
return true;

// The following are special cases that require activeTab explicitly. Normal
// extensions will never have full access to these pages (i.e., can never
// inject scripts or otherwise modify the page), but capturing the page can
// still be useful for e.g. screenshots. We allow these pages only if the
// extension has been explicitly granted activeTab, which serves as a
// stronger guarantee that the user wants to run the extension on the site.
// These origins include:
// - chrome:-scheme pages.
// - Other extension's pages.
// - data: URLs (which don't have a defined underlying origin).
// - The Chrome Web Store.
bool allowed_with_active_tab =
origin_url.SchemeIs(content::kChromeUIScheme) ||
origin_url.SchemeIs(kExtensionScheme) ||
// Note: The origin of a data: url is empty, so check the url itself.
document_url.SchemeIs(url::kDataScheme) ||
origin.IsSameOriginWith(
url::Origin::Create(ExtensionsClient::Get()->GetWebstoreBaseURL()));

if (!allowed_with_active_tab) {
if (error)
*error = access_error;
return false;
}
// If the extension has activeTab, these origins are allowed.
if (has_active_tab)
return true;

// Otherwise, access is denied.
if (error)
*error = manifest_errors::kActiveTabPermissionNotGranted;
return false;
}

void ChangeCurrentInputMethod(const InputMethodDescriptor& new_input_method) {
if (current_input_method_.id != new_input_method.id) {
previous_input_method_ = current_input_method_;
current_input_method_ = new_input_method;

// Change the keyboard layout to a preferred layout for the input method.
if (!input_method::SetCurrentKeyboardLayoutByName(
current_input_method_.keyboard_layout)) {
LOG(ERROR) << "Failed to change keyboard layout to "
<< current_input_method_.keyboard_layout;
}

// Ask the first observer to update preferences. We should not ask every
// observer to do so. Otherwise, we'll end up updating preferences many
// times when many observers are attached (ex. many windows are opened),
// which is unnecessary and expensive.
      ObserverListBase<Observer>::Iterator it(observers_);
      Observer* first_observer = it.GetNext();
if (first_observer) {
first_observer->PreferenceUpdateNeeded(this,
previous_input_method_,
current_input_method_);
}
}

// Update input method indicators (e.g. "US", "DV") in Chrome windows.
// For now, we have to do this every time to keep indicators updated. See
// comments near the FOR_EACH_OBSERVER call in FlushImeConfig() for details.
const size_t num_active_input_methods = GetNumActiveInputMethods();
    FOR_EACH_OBSERVER(Observer, observers_,
InputMethodChanged(this,
current_input_method_,
num_active_input_methods));
}

main(int argc, char **argv)
{
png_uint_32 opts = FAST_WRITE;
format_list formats;
const char *touch = NULL;
int log_pass = 0;
int redundant = 0;
int stride_extra = 0;
int retval = 0;
int c;

init_sRGB_to_d();
#if 0
init_error_via_linear();
#endif
format_init(&formats);

for (c=1; c<argc; ++c)
{
const char *arg = argv[c];

if (strcmp(arg, "--log") == 0)
log_pass = 1;
else if (strcmp(arg, "--fresh") == 0)
{
memset(gpc_error, 0, sizeof gpc_error);
memset(gpc_error_via_linear, 0, sizeof gpc_error_via_linear);
}
else if (strcmp(arg, "--file") == 0)
#        ifdef PNG_STDIO_SUPPORTED
opts |= READ_FILE;
#        else
return 77; /* skipped: no support */
#        endif
else if (strcmp(arg, "--memory") == 0)
opts &= ~READ_FILE;
else if (strcmp(arg, "--stdio") == 0)
#        ifdef PNG_STDIO_SUPPORTED
opts |= USE_STDIO;
#        else
return 77; /* skipped: no support */
#        endif
else if (strcmp(arg, "--name") == 0)
opts &= ~USE_STDIO;
else if (strcmp(arg, "--verbose") == 0)
opts |= VERBOSE;
else if (strcmp(arg, "--quiet") == 0)
opts &= ~VERBOSE;
else if (strcmp(arg, "--preserve") == 0)
opts |= KEEP_TMPFILES;
else if (strcmp(arg, "--nopreserve") == 0)
opts &= ~KEEP_TMPFILES;
else if (strcmp(arg, "--keep-going") == 0)
opts |= KEEP_GOING;
else if (strcmp(arg, "--fast") == 0)
opts |= FAST_WRITE;
else if (strcmp(arg, "--slow") == 0)
opts &= ~FAST_WRITE;
else if (strcmp(arg, "--accumulate") == 0)
opts |= ACCUMULATE;
else if (strcmp(arg, "--redundant") == 0)
redundant = 1;
else if (strcmp(arg, "--stop") == 0)
opts &= ~KEEP_GOING;
else if (strcmp(arg, "--strict") == 0)
opts |= STRICT;
else if (strcmp(arg, "--sRGB-16bit") == 0)
opts |= sRGB_16BIT;
else if (strcmp(arg, "--linear-16bit") == 0)
opts &= ~sRGB_16BIT;
else if (strcmp(arg, "--tmpfile") == 0)
{
if (c+1 < argc)
{
if (strlen(argv[++c]) >= sizeof tmpf)
{
fflush(stdout);
fprintf(stderr, "%s: %s is too long for a temp file prefix\n",
argv[0], argv[c]);
exit(99);

}

/* Safe: checked above */
            strcpy(tmpf, argv[c]);
}

else
{
fflush(stdout);
fprintf(stderr, "%s: %s requires a temporary file prefix\n",
argv[0], arg);
exit(99);
}
}
else if (strcmp(arg, "--touch") == 0)
{
if (c+1 < argc)
touch = argv[++c];

else
{
fflush(stdout);
fprintf(stderr, "%s: %s requires a file name argument\n",
argv[0], arg);
exit(99);
}
}
else if (arg[0] == '+')
{
png_uint_32 format = formatof(arg+1);

if (format > FORMAT_COUNT)
exit(99);

format_set(&formats, format);
}
else if (arg[0] == '-' && arg[1] != 0 && (arg[1] != '0' || arg[2] != 0))
{
fflush(stdout);
fprintf(stderr, "%s: unknown option: %s\n", argv[0], arg);
exit(99);
}
else
{
if (format_is_initial(&formats))
format_default(&formats, redundant);

if (arg[0] == '-')
{
const int term = (arg[1] == '0' ? 0 : '\n');
unsigned int ich = 0;

/* Loop reading files, use a static buffer to simplify this and just
* stop if the name gets to long.
*/
static char buffer[4096];

do
{
int ch = getchar();

/* Don't allow '\0' in file names, and terminate with '\n' or,
* for -0, just '\0' (use -print0 to find to make this work!)
*/
if (ch == EOF || ch == term || ch == 0)
{
buffer[ich] = 0;

if (ich > 0 && !test_one_file(buffer, &formats, opts,
stride_extra, log_pass))
retval = 1;

if (ch == EOF)
break;

ich = 0;
--ich; /* so that the increment below sets it to 0 again */
}

else
buffer[ich] = (char)ch;
} while (++ich < sizeof buffer);

if (ich)
{
buffer[32] = 0;
buffer[4095] = 0;
fprintf(stderr, "%s...%s: file name too long\n", buffer,
buffer+(4096-32));
exit(99);
}
}

else if (!test_one_file(arg, &formats, opts, stride_extra, log_pass))
retval = 1;
}
}

if (opts & ACCUMULATE)

{
unsigned int in;

printf("static png_uint_16 gpc_error[16/*in*/][16/*out*/][4/*a*/] =\n");
printf("{\n");
for (in=0; in<16; ++in)
{
unsigned int out;
printf(" { /* input: %s */\n ", format_names[in]);
for (out=0; out<16; ++out)
{
unsigned int alpha;
printf(" {");
for (alpha=0; alpha<4; ++alpha)
{
printf(" %d", gpc_error[in][out][alpha]);
if (alpha < 3) putchar(',');
}
printf(" }");
if (out < 15)
{
putchar(',');
if (out % 4 == 3) printf("\n ");
}
}
printf("\n }");

if (in < 15)
putchar(',');
else
putchar('\n');
}
printf("};\n");

printf("static png_uint_16 gpc_error_via_linear[16][4/*out*/][4] =\n");
printf("{\n");
for (in=0; in<16; ++in)
{
unsigned int out;
printf(" { /* input: %s */\n ", format_names[in]);
for (out=0; out<4; ++out)
{
unsigned int alpha;
printf(" {");
for (alpha=0; alpha<4; ++alpha)
{
printf(" %d", gpc_error_via_linear[in][out][alpha]);
if (alpha < 3) putchar(',');
}
printf(" }");
if (out < 3)
putchar(',');
}
printf("\n }");

if (in < 15)
putchar(',');
else
putchar('\n');
}
printf("};\n");

printf("static png_uint_16 gpc_error_to_colormap[8/*i*/][8/*o*/][4] =\n");
printf("{\n");
for (in=0; in<8; ++in)
{
unsigned int out;
printf(" { /* input: %s */\n ", format_names[in]);
for (out=0; out<8; ++out)
{
unsigned int alpha;
printf(" {");
for (alpha=0; alpha<4; ++alpha)
{
printf(" %d", gpc_error_to_colormap[in][out][alpha]);
if (alpha < 3) putchar(',');
}
printf(" }");
if (out < 7)
{
putchar(',');
if (out % 4 == 3) printf("\n ");
}
}
printf("\n }");

if (in < 7)
putchar(',');
else

putchar('\n');
}
printf("};\n");
}

if (retval == 0 && touch != NULL)
{
FILE *fsuccess = fopen(touch, "wt");

if (fsuccess != NULL)
{
int error = 0;
fprintf(fsuccess, "PNG simple API tests succeeded\n");
fflush(fsuccess);
error = ferror(fsuccess);

if (fclose(fsuccess) || error)
{
fflush(stdout);
fprintf(stderr, "%s: write failed\n", touch);
exit(99);
}
}

else
{
fflush(stdout);
fprintf(stderr, "%s: open failed\n", touch);
exit(99);
}
}

return retval;
}

