AcceleratedStaticBitmapImage::~AcceleratedStaticBitmapImage() {
// If the original SkImage was retained, it must be destroyed on the thread
// where it came from. In the same thread case, there is nothing to do because
// the regular destruction flow is fine.
if (original_skia_image_) {
std::unique_ptr<gpu::SyncToken> sync_token =
base::WrapUnique(new gpu::SyncToken(texture_holder_->GetSyncToken()));
    if (original_skia_image_thread_id_ !=
        Platform::Current()->CurrentThread()->ThreadId()) {
PostCrossThreadTask(
*original_skia_image_task_runner_, FROM_HERE,
CrossThreadBind(
&DestroySkImageOnOriginalThread, std::move(original_skia_image_),
std::move(original_skia_image_context_provider_wrapper_),
WTF::Passed(std::move(sync_token))));
} else {
DestroySkImageOnOriginalThread(
std::move(original_skia_image_),
std::move(original_skia_image_context_provider_wrapper_),
std::move(sync_token));
}
}
}

Block::Lacing Block::GetLacing() const
{
    const int value = int(m_flags & 0x06) >> 1;
    return static_cast<Lacing>(value);
}

next_format(png_bytep colour_type, png_bytep bit_depth,
   unsigned int* palette_number, int no_low_depth_gray)
{
if (*bit_depth == 0)
{
*colour_type = 0;
      if (no_low_depth_gray)
         *bit_depth = 8;
      else
*bit_depth = 1;
*palette_number = 0;
return 1;
}

   if (*colour_type == 3)
{
      /* Add multiple palettes for colour type 3. *
      if (++*palette_number < PALETTE_COUNT(*bit_depth))
return 1;

*palette_number = 0;
}

*bit_depth = (png_byte)(*bit_depth << 1);


/* Palette images are restricted to 8 bit depth */
if (*bit_depth <= 8
#     ifdef DO_16BIT
|| (*colour_type != 3 && *bit_depth <= 16)
#     endif
)
return 1;

/* Move to the next color type, or return 0 at the end. */
switch (*colour_type)
{
case 0:
*colour_type = 2;
*bit_depth = 8;
return 1;

case 2:
*colour_type = 3;
*bit_depth = 1;
return 1;

case 3:
*colour_type = 4;
*bit_depth = 8;
return 1;

case 4:
*colour_type = 6;
*bit_depth = 8;
return 1;

default:
return 0;
}
}

void UrlData::MergeFrom(const scoped_refptr<UrlData>& other) {
// We're merging from another UrlData that refers to the *same*
// resource, so when we merge the metadata, we can use the most
// optimistic values.
if (ValidateDataOrigin(other->data_origin_)) {
DCHECK(thread_checker_.CalledOnValidThread());
valid_until_ = std::max(valid_until_, other->valid_until_);
// set_length() will not override the length if already known.
set_length(other->length_);
cacheable_ |= other->cacheable_;
range_supported_ |= other->range_supported_;
if (last_modified_.is_null()) {
last_modified_ = other->last_modified_;
}
bytes_read_from_cache_ += other->bytes_read_from_cache_;
    // set_has_opaque_data() will not relax from opaque to non-opaque if already
    // opaque.
    set_has_opaque_data(other->has_opaque_data_);
multibuffer()->MergeFrom(other->multibuffer());
}
}

