int svc_rdma_sendto(struct svc_rqst *rqstp)
{
struct svc_xprt *xprt = rqstp->rq_xprt;
struct svcxprt_rdma *rdma =
container_of(xprt, struct svcxprt_rdma, sc_xprt);
	struct rpcrdma_msg *rdma_argp;
	struct rpcrdma_msg *rdma_resp;
	struct rpcrdma_write_array *wr_ary, *rp_ary;
	int ret;
	int inline_bytes;
struct page *res_page;
	struct svc_rdma_req_map *vec;
	u32 inv_rkey;
	__be32 *p;
	dprintk("svcrdma: sending response for rqstp=%p\n", rqstp);

	/* Get the RDMA request header. The receive logic always
	 * places this at the start of page 0.
*/
rdma_argp = page_address(rqstp->rq_pages[0]);
	svc_rdma_get_write_arrays(rdma_argp, &wr_ary, &rp_ary);
	inv_rkey = 0;
	if (rdma->sc_snd_w_inv)
		inv_rkey = svc_rdma_get_inv_rkey(rdma_argp, wr_ary, rp_ary);

	/* Build an req vec for the XDR *
	vec = svc_rdma_get_req_map(rdma);
	ret = svc_rdma_map_xdr(rdma, &rqstp->rq_res, vec, wr_ary != NULL);
	if (ret)
		goto err0;
	inline_bytes = rqstp->rq_res.len;

/* Create the RDMA response header. xprt->xpt_mutex,
* acquired in svc_send(), serializes RPC replies. The
* code path below that inserts the credit grant value
* into each transport header runs only inside this
* critical section.
*/
ret = -ENOMEM;
res_page = alloc_page(GFP_KERNEL);
if (!res_page)
goto err0;
rdma_resp = page_address(res_page);

	p = &rdma_resp->rm_xid;
	*p++ = rdma_argp->rm_xid;
	*p++ = rdma_argp->rm_vers;
*p++ = rdma->sc_fc_credits;
	*p++ = rp_ary ? rdma_nomsg : rdma_msg;

/* Start with empty chunks */
*p++ = xdr_zero;
*p++ = xdr_zero;
*p   = xdr_zero;

	/* Send any write-chunk data and build resp write-list *
	if (wr_ary) {
		ret = send_write_chunks(rdma, wr_ary, rdma_resp, rqstp, vec);
if (ret < 0)
			goto err1;
		inline_bytes -= ret + xdr_padsize(ret);
}
	/* Send any reply-list data and update resp reply-list *
	if (rp_ary) {
		ret = send_reply_chunks(rdma, rp_ary, rdma_resp, rqstp, vec);
if (ret < 0)
			goto err1;
		inline_bytes -= ret;
}

	/* Post a fresh Receive buffer _before_ sending the reply *
ret = svc_rdma_post_recv(rdma, GFP_KERNEL);
if (ret)
goto err1;
	ret = send_reply(rdma, rqstp, res_page, rdma_resp, vec,
			 inline_bytes, inv_rkey);
if (ret < 0)
goto err0;

	svc_rdma_put_req_map(rdma, vec);
	dprintk("svcrdma: send_reply returns %d\n", ret);
	return ret;

err1:
put_page(res_page);
err0:
	svc_rdma_put_req_map(rdma, vec);
pr_err("svcrdma: Could not send reply, err=%d. Closing transport.\n",
ret);
	set_bit(XPT_CLOSE, &rdma->sc_xprt.xpt_flags);
return -ENOTCONN;
}

static bool CheckDts(const uint8_t* buffer, int buffer_size) {
// Reference: ETSI TS 102 114 V1.3.1 (2011-08)
// (http://www.etsi.org/deliver/etsi_ts/102100_102199/102114/01.03.01_60/ts_102114v010301p.pdf)
RCHECK(buffer_size > 11);

int offset = 0;
while (offset + 11 < buffer_size) {
BitReader reader(buffer + offset, 11);

// Verify sync word.
RCHECK(ReadBits(&reader, 32) == 0x7ffe8001);

// Skip frame type and deficit sample count.
reader.SkipBits(1 + 5);

// Verify CRC present flag.
RCHECK(ReadBits(&reader, 1) == 0);  // CPF must be 0.

// Verify number of PCM sample blocks.
RCHECK(ReadBits(&reader, 7) >= 5);

// Verify primary frame byte size.
int frame_size = ReadBits(&reader, 14);
RCHECK(frame_size >= 95);

// Skip audio channel arrangement.
reader.SkipBits(6);

// Verify core audio sampling frequency is an allowed value.
    RCHECK(kSamplingFrequencyValid[ReadBits(&reader, 4)]);

// Verify transmission bit rate is valid.
RCHECK(ReadBits(&reader, 5) <= 25);

// Verify reserved field is 0.
RCHECK(ReadBits(&reader, 1) == 0);

// Skip dynamic range flag, time stamp flag, auxiliary data flag, and HDCD.
reader.SkipBits(1 + 1 + 1 + 1);

// Verify extension audio descriptor flag is an allowed value.
    RCHECK(kExtAudioIdValid[ReadBits(&reader, 3)]);

// Skip extended coding flag and audio sync word insertion flag.
reader.SkipBits(1 + 1);

// Verify low frequency effects flag is an allowed value.
RCHECK(ReadBits(&reader, 2) != 3);

offset += frame_size + 1;
}
return true;
}

static M_bool M_fs_check_overwrite_allowed(const char *p1, const char *p2, M_uint32 mode)
{
M_fs_info_t  *info = NULL;
char         *pold = NULL;
char         *pnew = NULL;
M_fs_type_t   type;
M_bool        ret  = M_TRUE;

if (mode & M_FS_FILE_MODE_OVERWRITE)
return M_TRUE;

/* If we're not overwriting we need to verify existance.
*
* For files we need to check if the file name exists in the
* directory it's being copied to.
*
* For directories we need to check if the directory name
* exists in the directory it's being copied to.
*/

if (M_fs_info(&info, p1, M_FS_PATH_INFO_FLAGS_BASIC) != M_FS_ERROR_SUCCESS)
return M_FALSE;

type = M_fs_info_get_type(info);
M_fs_info_destroy(info);

if (type != M_FS_TYPE_DIR) {
/* File exists at path. */
		if (M_fs_perms_can_access(p2, M_FS_PERMS_MODE_NONE) == M_FS_ERROR_SUCCESS)
		{
ret = M_FALSE;
goto done;
}
}

/* Is dir */
pold = M_fs_path_basename(p1, M_FS_SYSTEM_AUTO);
pnew = M_fs_path_join(p2, pnew, M_FS_SYSTEM_AUTO);
if (M_fs_perms_can_access(pnew, M_FS_PERMS_MODE_NONE) == M_FS_ERROR_SUCCESS) {
ret = M_FALSE;
goto done;
}

done:
M_free(pnew);
M_free(pold);
return ret;
}

