static int hugetlbfs_statfs(struct dentry *dentry, struct kstatfs *buf)
{
struct hugetlbfs_sb_info *sbinfo = HUGETLBFS_SB(dentry->d_sb);
struct hstate *h = hstate_inode(dentry->d_inode);

buf->f_type = HUGETLBFS_MAGIC;
buf->f_bsize = huge_page_size(h);
if (sbinfo) {
spin_lock(&sbinfo->stat_lock);
/* If no limits set, just report 0 for max/free/used
* blocks, like simple_statfs() */
		if (sbinfo->max_blocks >= 0) {
			buf->f_blocks = sbinfo->max_blocks;
			buf->f_bavail = buf->f_bfree = sbinfo->free_blocks;
buf->f_files = sbinfo->max_inodes;
buf->f_ffree = sbinfo->free_inodes;
}
spin_unlock(&sbinfo->stat_lock);
}
buf->f_namelen = NAME_MAX;
return 0;
}

int key_reject_and_link(struct key *key,
unsigned timeout,
unsigned error,
struct key *keyring,
struct key *authkey)
{
struct assoc_array_edit *edit;
struct timespec now;
int ret, awaken, link_ret = 0;

key_check(key);
key_check(keyring);

awaken = 0;
ret = -EBUSY;

if (keyring) {
if (keyring->restrict_link)
return -EPERM;

link_ret = __key_link_begin(keyring, &key->index_key, &edit);
}

mutex_lock(&key_construction_mutex);

/* can't instantiate twice */
if (!test_bit(KEY_FLAG_INSTANTIATED, &key->flags)) {
/* mark the key as being negatively instantiated */
atomic_inc(&key->user->nikeys);
key->reject_error = -error;
smp_wmb();
set_bit(KEY_FLAG_NEGATIVE, &key->flags);
set_bit(KEY_FLAG_INSTANTIATED, &key->flags);
now = current_kernel_time();
key->expiry = now.tv_sec + timeout;
key_schedule_gc(key->expiry + key_gc_delay);

if (test_and_clear_bit(KEY_FLAG_USER_CONSTRUCT, &key->flags))
awaken = 1;

ret = 0;

/* and link it into the destination keyring */
if (keyring && link_ret == 0)
__key_link(key, &edit);

/* disable the authorisation key */
if (authkey)
key_revoke(authkey);
}

mutex_unlock(&key_construction_mutex);

	if (keyring)
__key_link_end(keyring, &key->index_key, edit);

/* wake up anyone waiting for a key to be constructed */
if (awaken)
wake_up_bit(&key->flags, KEY_FLAG_USER_CONSTRUCT);

return ret == 0 ? link_ret : ret;
}

bool WebPluginDelegateProxy::BindFakePluginWindowHandle(bool opaque) {
gfx::PluginWindowHandle fake_window = NULL;
if (render_view_)
fake_window = render_view_->AllocateFakePluginWindowHandle(opaque);
// If we aren't running on 10.6, this allocation will fail.
if (!fake_window)
return false;
OnSetWindow(fake_window);
if (!Send(new PluginMsg_SetFakeAcceleratedSurfaceWindowHandle(instance_id_,
fake_window))) {
return false;
}

// Since this isn't a real window, it doesn't get initial size and location
// information the way a real windowed plugin would, so we need to feed it its
// starting geometry.
webkit_glue::WebPluginGeometry geom;
geom.window = fake_window;
geom.window_rect = plugin_rect_;
  geom.clip_rect = gfx::Rect(0, 0, plugin_rect_.width(), plugin_rect_.height());
geom.rects_valid = true;
geom.visible = true;
render_view_->DidMovePlugin(geom);
// Invalidate the plugin region to ensure that the move event actually gets
// dispatched (for a plugin on an otherwise static page).
render_view_->didInvalidateRect(WebKit::WebRect(plugin_rect_.x(),
plugin_rect_.y(),
plugin_rect_.width(),
plugin_rect_.height()));

return true;
}

tt_cmap10_validate( FT_Byte*      table,
FT_Validator  valid )
{
FT_Byte*  p = table + 4;
FT_ULong  length, count;


if ( table + 20 > valid->limit )
FT_INVALID_TOO_SHORT;

length = TT_NEXT_ULONG( p );
p      = table + 16;
count  = TT_NEXT_ULONG( p );

    if ( table + length > valid->limit || length < 20 + count * 2 )
FT_INVALID_TOO_SHORT;

/* check glyph indices */
{
FT_UInt  gindex;


for ( ; count > 0; count-- )
{
gindex = TT_NEXT_USHORT( p );
if ( gindex >= TT_VALID_GLYPH_COUNT( valid ) )
FT_INVALID_GLYPH_ID;
}
}

return SFNT_Err_Ok;
}

DefragVlanQinQTest(void)
{
Packet *p1 = NULL, *p2 = NULL, *r = NULL;
int ret = 0;

DefragInit();

    p1 = BuildTestPacket(1, 0, 1, 'A', 8);
if (p1 == NULL)
goto end;
    p2 = BuildTestPacket(1, 1, 0, 'B', 8);
if (p2 == NULL)
goto end;

/* With no VLAN IDs set, packets should re-assemble. */
if ((r = Defrag(NULL, NULL, p1, NULL)) != NULL)
goto end;
if ((r = Defrag(NULL, NULL, p2, NULL)) == NULL)
goto end;
SCFree(r);

/* With mismatched VLANs, packets should not re-assemble. */
p1->vlan_id[0] = 1;
p2->vlan_id[0] = 1;
p1->vlan_id[1] = 1;
p2->vlan_id[1] = 2;
if ((r = Defrag(NULL, NULL, p1, NULL)) != NULL)
goto end;
if ((r = Defrag(NULL, NULL, p2, NULL)) != NULL)
goto end;

/* Pass. */
ret = 1;

end:
if (p1 != NULL)
SCFree(p1);
if (p2 != NULL)
SCFree(p2);
DefragDestroy();

return ret;
}

