std::string SanitizeFrontendQueryParam(
    const std::string& key,
    const std::string& value) {
  // Convert boolean flags to true.
  if (key == "can_dock" || key == "debugFrontend" || key == "experiments" ||
      key == "isSharedWorker" || key == "v8only" || key == "remoteFrontend")
    return "true";
  // Pass connection endpoints as is.
  if (key == "ws" || key == "service-backend")
    return SanitizeEndpoint(value);
  // Only support undocked for old frontends.
  if (key == "dockSide" && value == "undocked")
    return value;
  if (key == "panel" && (value == "elements" || value == "console"))
    return value;
  if (key == "remoteBase")
    return SanitizeRemoteBase(value);
  if (key == "remoteFrontendUrl")
    return SanitizeRemoteFrontendURL(value);
  return std::string();
}

static void CopyTransportDIBHandleForMessage(
const TransportDIB::Handle& handle_in,
    TransportDIB::Handle* handle_out) {
#if defined(OS_MACOSX)
// On Mac, TransportDIB::Handle is typedef'ed to FileDescriptor, and
// FileDescriptor message fields needs to remain valid until the message is
// sent or else the sendmsg() call will fail.
if ((handle_out->fd = HANDLE_EINTR(dup(handle_in.fd))) < 0) {
PLOG(ERROR) << "dup()";
return;
}
handle_out->auto_close = true;
#else
// Don't need to do anything special for other platforms.
*handle_out = handle_in;
#endif
}

